"""The agent contract: one job, declared inputs (so unchanged work is reused), decisions and self-checks."""

from __future__ import annotations

import subprocess
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Callable

import numpy as np

from ... import media
from ..model import ASPECTS, AgentRun, Clip, Project, Settings


@dataclass
class Ctx:
    project: Project
    root: Path
    emit: Callable[..., None]
    hints: dict[str, dict] = field(default_factory=dict)

    @property
    def settings(self) -> Settings:
        return self.project.settings

    @property
    def skill(self) -> dict:
        return self.project.skill

    def abs(self, p: str) -> Path:
        q = Path(p)
        return q if q.is_absolute() else self.root / q

    def rel(self, p: Path) -> str:
        try:
            return p.resolve().relative_to(self.root.resolve()).as_posix()
        except ValueError:
            return str(p)

    def ffmpeg(self, args: list[str], timeout: float = 1800) -> subprocess.CompletedProcess:
        """FFmpeg with the project folder as working directory, so filter arguments use short relative paths."""
        return media.run(args, timeout=timeout, cwd=self.root)


class Agent:
    key = ""
    title = ""
    role = ""
    icon = ""
    color = ""
    needs: tuple[str, ...] = ()

    def inputs(self, ctx: Ctx) -> Any:
        """Everything this agent's output depends on. Unchanged inputs => the previous result is reused."""
        return None

    def run(self, ctx: Ctx, rep: AgentRun) -> None:
        raise NotImplementedError

    def say(self, ctx: Ctx, msg: str, kind: str = "log", **data: Any) -> None:
        ctx.emit(self.key, kind, msg, **data)

    def decide(self, ctx: Ctx, rep: AgentRun, msg: str) -> None:
        rep.decisions.append(msg)
        ctx.emit(self.key, "decision", msg)

    def check(self, ctx: Ctx, rep: AgentRun, name: str, ok: bool, detail: str, owner: str | None = None,
              hint: dict | None = None) -> bool:
        rep.checks.append({"name": name, "ok": bool(ok), "detail": detail, "owner": owner or self.key,
                           "hint": hint or {}})
        ctx.emit(self.key, "check", f"{'PASS' if ok else 'FAIL'} {name}: {detail}", ok=bool(ok), name=name)
        return bool(ok)


# --- shared helpers ------------------------------------------------------------------------------------------

def frame_size(s: Settings) -> tuple[int, int]:
    aw, ah = ASPECTS.get(s.aspect, (9, 16))
    short = int(s.resolution)
    if aw >= ah:
        return round(short * aw / ah / 2) * 2, short
    return short, round(short * ah / aw / 2) * 2


COMMON_FPS = (23.976, 24.0, 25.0, 29.97, 30.0, 50.0, 59.94, 60.0)


def out_fps(p: Project) -> float:
    if p.settings.fps:
        return float(p.settings.fps)
    if not p.clips:
        return 30.0
    weights: dict[float, float] = {}
    for c in p.clips:
        f = min(COMMON_FPS, key=lambda x: abs(x - (c.fps or 30)))
        weights[f] = weights.get(f, 0) + c.duration
    f = max(weights, key=weights.get)
    return 30.0 if f > 60 else f


def fps_arg(f: float) -> str:
    return {23.976: "24000/1001", 29.97: "30000/1001", 59.94: "60000/1001"}.get(round(f, 3), f"{f:g}")


def load_analysis(ctx: Ctx, clip: Clip) -> dict[str, np.ndarray]:
    with np.load(ctx.abs(clip.analysis)) as d:
        return {k: d[k] for k in d.files}


def save_jpg(arr: np.ndarray, out: Path, quality: int = 3) -> Path:
    h, w = arr.shape[:2]
    out.parent.mkdir(parents=True, exist_ok=True)
    proc = subprocess.run([media._bin("ffmpeg"), "-hide_banner", "-nostdin", "-v", "error", "-y", "-f", "rawvideo",
                           "-pix_fmt", "rgb24", "-s", f"{w}x{h}", "-i", "pipe:0", "-q:v", str(quality), str(out)],
                          input=np.ascontiguousarray(arr).tobytes(), capture_output=True, timeout=120)
    if proc.returncode != 0:
        raise media.RenderError("could not write still", proc.stderr.decode("utf-8", "replace")[-300:])
    return out


def usable_ranges(clip: Clip, guard: float = 0.12) -> list[tuple[float, float]]:
    """Stretches of a clip between camera cuts, with a guard so no frame of the neighbouring shot leaks in."""
    edges = [0.0, *clip.cuts, clip.duration]
    out = []
    for a, b in zip(edges, edges[1:]):
        lo, hi = a + (guard if a > 0 else 0.04), b - (guard if b < clip.duration else 0.06)
        if hi - lo > 0.2:
            out.append((round(lo, 3), round(hi, 3)))
    return out


def retime(timeline: list) -> None:
    """Timeline positions from lengths; a transition overlaps the two segments by its duration."""
    t = 0.0
    for i, s in enumerate(timeline):
        if i:
            t -= s.trans_d if s.trans != "cut" else 0.0
        s.start = round(t, 4)
        t += s.length

"""Motion designer: the skill's camera moves and transitions, applied where the footage allows them.

Slow push-ins only on shots that hold still, alternating punch-ins on bursts and jump cuts (so a jump in the
same take reads as intentional), punch zooms on the beat, whip pans into and out of bursts, dissolves,
light flashes, dips to black, slow motion only when the source frame rate makes it smooth. Transitions need
footage beyond the cut ("handles"); when a shot has none, it stays a hard cut and says so.
"""

from __future__ import annotations

import numpy as np

from ..model import AgentRun
from .base import Agent, Ctx, frame_size, load_analysis, out_fps, retime, usable_ranges


class MotionDesigner(Agent):
    key, title, icon, color = "motion", "Motion", "motion", "#e0af68"
    role = "adds the skill's moves: push-ins, punch zooms, jump-cut zooms, whip pans, dissolves, flashes, slow motion, fades"
    needs = ("reframer",)

    def inputs(self, ctx: Ctx):
        s = ctx.settings
        return [ctx.skill.get("motion"), s.transitions, s.slowmo, out_fps(ctx.project), s.aspect,
                [(g.kind, g.clip, g.src_in, g.src_out, g.role, g.x0, g.x1, g.fill, g.card) for g in ctx.project.timeline]]

    def run(self, ctx: Ctx, rep: AgentRun) -> None:
        p, s = ctx.project, ctx.settings
        M = dict(ctx.skill.get("motion") or {})
        fps = out_fps(p)
        tl = p.timeline
        for g in tl:  # start from a clean slate (the Cutter's timeline)
            g.zoom0 = g.zoom1 = 1.0
            g.zoom_ease, g.trans, g.trans_d, g.fade_in, g.fade_out, g.speed = "linear", "cut", 0.0, 0.0, 0.0, 1.0
        cache: dict[str, dict] = {}

        def action(g) -> float:
            c = p.clip(g.clip)
            d = cache.setdefault(c.id, load_analysis(ctx, c))
            sel = (d["t"] >= g.src_in) & (d["t"] <= g.src_out)
            m = d["motion"][sel] if sel.any() else d["motion"]
            ref = np.percentile(d["motion"], 75) + 1e-6
            return float(np.clip(m.mean() / ref, 0, 2))

        counts = {"push": 0, "jump": 0, "burst": 0, "punch": 0}
        burst_k = 0
        prev = None
        for g in tl:
            if g.kind != "clip":
                prev = None
                continue
            jz = float(M.get("jump_zoom") or 1.0)
            same_take = (prev is not None and prev.clip == g.clip and 0 <= g.src_in - prev.src_out < 2.5
                         and not any(prev.src_out <= cut <= g.src_in for cut in p.clip(g.clip).cuts))
            if g.role == "burst":
                z = jz if burst_k % 2 else 1.0
                g.zoom0 = g.zoom1 = z
                burst_k += 1
                counts["burst"] += 1
            elif (same_take or g.role == "jump") and jz > 1 and prev is not None:
                z = 1.0 if prev.zoom1 > 1.001 else jz
                g.zoom0 = g.zoom1 = z
                counts["jump"] += 1
            elif M.get("push") and g.role in ("hold", "hook", "outro") and action(g) < 0.55:
                g.zoom0, g.zoom1 = 1.0, 1.0 + float(M["push"])
                counts["push"] += 1
            if M.get("punch") and g.role in ("burst", "hook", "hold"):
                g.zoom0, g.zoom1, g.zoom_ease = max(g.zoom1, 1.0) + float(M["punch"]), max(g.zoom1, 1.0), "punch"
                counts["punch"] += 1
            prev = g
        msg = [f"{v} {k}" + ("es" if k == "push" and v != 1 else "s" if v != 1 else "") for k, v in counts.items() if v]
        if msg:
            self.decide(ctx, rep, "moves: " + ", ".join(msg)
                        + (" (push-ins only on shots that hold still)" if counts["push"] else ""))

        # slow motion: only when the source has the frames for it
        if s.slowmo and M.get("slowmo"):
            sp = float(M["slowmo"])
            for g in tl:
                if g.kind == "clip" and g.role == "outro":
                    c = p.clip(g.clip)
                    if c.fps >= fps / sp * 0.95:
                        L = g.length
                        mid = (g.src_in + g.src_out) / 2
                        g.speed = sp
                        g.src_in, g.src_out = round(mid - L * sp / 2, 4), round(mid + L * sp / 2, 4)
                        self.decide(ctx, rep, f"outro at {sp:.0%} speed ({c.fps:g} fps source → real slow motion)")
                    else:
                        self.decide(ctx, rep, f"no slow motion: {c.fps:g} fps footage would stutter at {sp:.0%} "
                                              f"(needs {fps / sp:.0f} fps)")

        # transitions
        made, refused = [], 0
        if s.transitions:
            pairs = [(a, b) for a, b in zip(tl, tl[1:]) if a.kind == "clip" and b.kind == "clip"]
            for n, (a, b) in enumerate(pairs, 1):
                kind = None
                into_burst = b.role == "burst" and a.role != "burst"
                out_burst = a.role == "burst" and b.role != "burst"
                if M.get("whip") and (into_burst or out_burst):
                    kind = ("whip", 0.2)
                elif M.get("flash") and (into_burst or (a.clip != b.clip and n % 2 == 1) or (M.get("cadence") and n % 3 == 0)):
                    kind = ("flash", 0.16)
                elif M.get("dissolve"):
                    kind = ("dissolve", float(M["dissolve"]))
                elif M.get("fadeblack") and n % int(M["fadeblack"]) == 0 and a.role != "burst" and b.role != "burst":
                    a.fade_out, b.fade_in = 0.3, 0.3
                    made.append("dip")
                    continue
                if not kind:
                    continue
                name, d = kind
                room_a = self._room_after(p, a)
                room_b = self._room_before(p, b)
                need = d / 2
                avail = min(room_a / a.speed, room_b / b.speed)
                if avail < 0.06:
                    refused += 1
                    continue
                need = min(need, avail)
                a.src_out = round(a.src_out + need * a.speed, 4)
                b.src_in = round(b.src_in - need * b.speed, 4)
                b.trans, b.trans_d = name, round(need * 2, 4)
                made.append(name)
        if made:
            kinds = {k: made.count(k) for k in dict.fromkeys(made)}
            self.decide(ctx, rep, "transitions: " + ", ".join(f"{v} {k}" for k, v in kinds.items())
                        + (f"; {refused} kept as hard cuts (no footage beyond the cut)" if refused else ""))
        elif refused:
            self.decide(ctx, rep, f"{refused} transition(s) kept as hard cuts: no footage beyond the cut")

        clips = [g for g in tl if g.kind == "clip"]
        if clips:
            if M.get("fade_in") and tl[0].kind == "clip":
                clips[0].fade_in = max(clips[0].fade_in, float(M["fade_in"]))
            fo = float(M.get("fade_out") or 0)
            if tl[-1].kind == "card":
                fo = max(fo, 0.5)
            if fo:
                clips[-1].fade_out = max(clips[-1].fade_out, min(fo, clips[-1].length * 0.6))
        # frame-accurate lengths
        for g in tl:
            n = max(2, int(round(g.length * fps)))
            if g.kind == "card":
                g.card = round(n / fps, 4)
            else:
                g.src_out = round(g.src_in + n / fps * g.speed, 4)
            if g.trans != "cut":
                g.trans_d = max(2, int(round(g.trans_d * fps))) / fps
        retime(tl)
        short = [g.id for g in tl if g.length < 2 / fps + 1e-6]
        self.check(ctx, rep, "no flash frames", not short, "every segment is at least 2 frames" if not short else f"segments {short}")
        W, H = frame_size(s)
        rep.summary = f"{len(made)} transitions · {sum(counts.values())} moves · {fps:g} fps"

    @staticmethod
    def _range(p, g) -> tuple[float, float]:
        c = p.clip(g.clip)
        for lo, hi in usable_ranges(c, guard=0.06):
            if lo - 1e-3 <= g.src_in and g.src_out <= hi + 1e-3:
                return lo, hi
        return g.src_in, g.src_out

    def _room_after(self, p, g) -> float:
        return max(0.0, self._range(p, g)[1] - g.src_out)

    def _room_before(self, p, g) -> float:
        return max(0.0, g.src_in - self._range(p, g)[0])

