"""The assembly line: runs the crew as a dependency graph.

Agents whose inputs are ready start at once (intake, reference and music together; colorist next to the
cutter; typographer next to the mixer). An agent whose inputs haven't changed since its last run is reused
instead of re-run, so a tweak to the story text re-runs only the typographer, export and QA. The project is
checkpointed after every agent (a crash resumes where it stopped), and QA failures go back to the agent
that owns them, with a fix, up to two rounds.
"""

from __future__ import annotations

import contextvars
import hashlib
import json
import secrets
import threading
import time
import traceback
from concurrent.futures import FIRST_COMPLETED, ThreadPoolExecutor, wait
from pathlib import Path

import neatlogs

from .. import obs
from ..config import settings
from . import skills
from .agents import BY_KEY, CREW, PREP
from .agents.base import Ctx
from .model import AgentRun, Project

ROOT = settings.projects_dir / "studio"
VERSION = "studio-1"
ORDER = [a.key for a in CREW]


class Bus:
    """Live events for one project (the UI listens through server-sent events)."""

    def __init__(self) -> None:
        self.events: list[dict] = []
        self.cond = threading.Condition()

    def emit(self, ev: dict) -> None:
        with self.cond:
            ev["i"] = len(self.events)
            self.events.append(ev)
            self.cond.notify_all()

    def since(self, i: int, timeout: float = 15.0) -> list[dict]:
        with self.cond:
            if len(self.events) <= i:
                self.cond.wait(timeout)
            return self.events[i:]


_BUSES: dict[str, Bus] = {}
_PROJECTS: dict[str, Project] = {}
_RUN_LOCKS: dict[str, threading.Lock] = {}
_SAVE_LOCK = threading.Lock()


def bus(pid: str) -> Bus:
    return _BUSES.setdefault(pid, Bus())


def project_dir(pid: str) -> Path:
    return ROOT / pid


def new_project(name: str = "untitled edit") -> Project:
    pid = time.strftime("%Y%m%d-%H%M%S") + "-" + secrets.token_hex(2)
    p = Project(id=pid, name=name)
    for sub in ("media", "analysis", "looks", "stills", "render"):
        (project_dir(pid) / sub).mkdir(parents=True, exist_ok=True)
    _PROJECTS[pid] = p
    save(p)
    return p


def load(pid: str) -> Project:
    if pid not in _PROJECTS:
        path = project_dir(pid) / "project.json"
        if not path.exists():
            raise KeyError(pid)
        p = Project.model_validate_json(path.read_text(encoding="utf-8"))
        if p.state in ("running", "preparing"):  # the process stopped mid-run: everything finished is checkpointed
            p.state = "ready" if p.clips else "empty"
            for a in p.agents.values():
                if a.status in ("working", "waiting", "fixing"):
                    a.status = "idle"
        _PROJECTS[pid] = p
    return _PROJECTS[pid]


def dump(p: Project) -> str:
    for _ in range(5):
        try:
            return p.model_dump_json()
        except RuntimeError:  # an agent was mutating a dict mid-serialisation; try again
            time.sleep(0.02)
    return p.model_dump_json()


def save(p: Project) -> None:
    with _SAVE_LOCK:
        d = project_dir(p.id)
        d.mkdir(parents=True, exist_ok=True)
        tmp = d / "project.json.tmp"
        tmp.write_text(dump(p), encoding="utf-8")
        tmp.replace(d / "project.json")


def list_projects() -> list[dict]:
    out = []
    if ROOT.exists():
        for d in sorted(ROOT.iterdir(), reverse=True):
            f = d / "project.json"
            if f.exists():
                try:
                    p = load(d.name)
                    out.append({"id": p.id, "name": p.name, "state": p.state, "clips": len(p.clips),
                                "poster": f"/p/{p.id}/{p.outputs.get('poster') or (p.clips[0].poster if p.clips else '')}",
                                "created": p.created, "duration": p.duration})
                except Exception:
                    continue
    return out


def run_lock(pid: str) -> threading.Lock:
    return _RUN_LOCKS.setdefault(pid, threading.Lock())


class Line:
    def __init__(self, p: Project, only: tuple[str, ...] | None = None):
        self.p = p
        self.root = project_dir(p.id)
        self.bus = bus(p.id)
        self.only = only
        self.events_path = self.root / "events.jsonl"

    # --- events -----------------------------------------------------------------------------------------------
    def emit(self, agent: str, kind: str, msg: str, **data) -> None:
        ev = {"t": round(time.time(), 3), "agent": agent, "kind": kind, "msg": msg, **data}
        self.bus.emit(ev)
        with self.events_path.open("a", encoding="utf-8") as f:
            f.write(json.dumps(ev, default=str) + "\n")
        if kind not in ("progress",):
            obs.console.print(f"[dim]\\[{agent:<11}][/dim] {msg}")

    def status(self, key: str, rep: AgentRun) -> None:
        self.emit(key, "status", f"{key}: {rep.status}", status=rep.status, summary=rep.summary, preview=rep.preview,
                  before=rep.before, seconds=rep.seconds)

    # --- skill ---------------------------------------------------------------------------------------------------
    def resolve_skill(self) -> None:
        s = self.p.settings
        sk = skills.get(s.skill)
        ref = self.p.reference
        if ref and ref.profile and s.match_reference:
            sk = skills.with_reference(sk, ref.profile, s.reference_strength)
        self.p.skill = sk

    # --- one agent -----------------------------------------------------------------------------------------------
    def fingerprint(self, key: str, ctx: Ctx) -> str:
        a = BY_KEY[key]
        ups = [self.p.agents[n].fingerprint for n in a.needs if n in self.p.agents]
        raw = json.dumps([VERSION, key, a.inputs(ctx), ups, ctx.hints.get(key)], sort_keys=True, default=str)
        return hashlib.sha1(raw.encode()).hexdigest()[:16]

    def outputs_ok(self, key: str) -> bool:
        p, r = self.p, self.root
        if key == "export":
            return (r / "final.mp4").exists()
        if key == "mixer":
            return bool(p.audio.file) and (r / p.audio.file).exists()
        if key == "typographer":
            return (r / "render" / "text.ass").exists()
        if key == "colorist":
            return all((r / v).exists() for v in (p.look.get("luts") or {}).values()) and bool(p.look.get("luts"))
        if key == "intake":
            return all(c.analysis and (r / c.analysis).exists() for c in p.clips)
        if key in ("cutter", "reframer", "motion"):
            return bool(p.stages.get(key))
        return True

    def run_agent(self, ctx: Ctx, key: str) -> bool:
        agent = BY_KEY[key]
        old = self.p.agents.get(key)
        fp = self.fingerprint(key, ctx)
        if old and old.fingerprint == fp and old.status in ("done", "cached", "skipped") and self.outputs_ok(key):
            if old.status != "skipped":
                old.status = "cached"
            self.status(key, old)
            return True
        rep = AgentRun(key=key, status="working", started=time.time(), fingerprint=fp)
        self.p.agents[key] = rep
        self.status(key, rep)
        kind = "GUARDRAIL" if key == "qa" else "AGENT"
        try:
            neatlogs.span(kind=kind, name=f"agent.{key}", role=agent.title, goal=agent.role)(agent.run)(ctx, rep)
            if rep.status == "working":
                rep.status = "done"
            return True
        except Exception as e:  # noqa: BLE001 - an agent failure stops the line with a clear message
            rep.status = "failed"
            rep.summary = f"{type(e).__name__}: {e}"
            tail = getattr(e, "tail", "")
            self.emit(key, "fail", rep.summary + (f" | {tail[-300:]}" if tail else ""), trace=traceback.format_exc()[-1500:])
            return False
        finally:
            rep.ended = time.time()
            rep.seconds = round(rep.ended - (rep.started or rep.ended), 2)
            self.status(key, rep)

    # --- the graph -----------------------------------------------------------------------------------------------
    def dag(self, ctx: Ctx, keys: list[str]) -> bool:
        needs = {k: [n for n in BY_KEY[k].needs if n in keys] for k in keys}
        pending, done, running, failed = set(keys), set(), {}, False
        for k in keys:
            rep = self.p.agents.setdefault(k, AgentRun(key=k))
            if rep.status not in ("fixing",):
                rep.status = "waiting"
            self.status(k, rep)
        with ThreadPoolExecutor(4) as ex:
            while pending or running:
                for k in sorted(pending, key=ORDER.index):
                    if not failed and all(n in done for n in needs[k]):
                        pending.discard(k)
                        running[ex.submit(contextvars.copy_context().run, self.run_agent, ctx, k)] = k
                if not running:
                    break
                fin, _ = wait(running, return_when=FIRST_COMPLETED)
                for f in fin:
                    k = running.pop(f)
                    if not f.result():
                        failed = True
                        pending.clear()
                    done.add(k)
                    if k == "reference":
                        self.resolve_skill()
                    save(self.p)
        for k in keys:
            rep = self.p.agents[k]
            if rep.status == "waiting":
                rep.status = "idle"
                self.status(k, rep)
        return not failed

    def run(self) -> Project:
        with run_lock(self.p.id):
            return neatlogs.span(kind="WORKFLOW", name="studio.line")(self._run)()

    def _run(self) -> Project:
        p = self.p
        t0 = time.time()
        p.state = "preparing" if self.only else "running"
        p.error = None
        p.trace_id = obs.current_trace_id() or p.trace_id
        obs.set_attrs(project=p.id, skill=p.settings.skill, aspect=p.settings.aspect)
        self.resolve_skill()
        ctx = Ctx(project=p, root=self.root, emit=self.emit, hints=p.hints)
        keys = list(self.only) if self.only else ORDER
        self.emit("line", "line", f"line started: {len(keys)} agents, skill {p.skill.get('label')}", state=p.state)
        ok = True
        before = {k: (p.agents[k].fingerprint if k in p.agents else None) for k in keys}
        for loop in range(3):
            ok = self.dag(ctx, keys)
            if not ok or self.only:
                break
            failed = [c for c in p.agents["qa"].checks if not c["ok"]]
            if not failed:
                break
            if loop == 2:
                self.emit("qa", "decision", f"{len(failed)} check(s) still failing after two rounds of fixes: delivered with notes")
                break
            sent = set()
            for c in failed:
                owner, hint = c.get("owner"), c.get("hint") or {}
                if owner not in BY_KEY or owner == "qa":
                    continue
                merged = dict(ctx.hints.get(owner, {}))
                for k, v in hint.items():
                    if k == "avoid":
                        merged["avoid"] = merged.get("avoid", []) + v
                    elif k == "boost_ref":
                        merged[k] = round(merged.get(k, 0) + v, 3)
                    elif k == "length_scale":
                        merged[k] = round(merged.get(k, 1.0) * v, 3)
                    else:
                        merged[k] = v
                merged["round"] = loop + 1
                ctx.hints[owner] = merged
                sent.add(owner)
                self.emit("qa", "sendback", f"{c['name']} failed ({c['detail']}) → back to {BY_KEY[owner].title}",
                          owner=owner)
            if not sent:
                break
            for o in sent:
                p.agents[o].status = "fixing"
                self.status(o, p.agents[o])
            p.loops = loop + 1
        p.hints = ctx.hints
        ran = [k for k in keys if p.agents.get(k) and p.agents[k].fingerprint != before.get(k)]
        cached = [k for k in keys if p.agents.get(k) and p.agents[k].status == "cached"]
        secs = round(time.time() - t0, 1)
        if not self.only:
            p.runs.append({"at": t0, "seconds": secs, "ran": ran, "cached": cached, "loops": p.loops, "ok": ok,
                           "skill": p.settings.skill})
        p.state = ("done" if p.outputs.get("video") and not self.only else "ready") if ok else "failed"
        if not ok:
            p.error = next((a.summary for a in p.agents.values() if a.status == "failed"), "an agent failed")
        save(p)
        self.emit("line", "line", f"line {'finished' if ok else 'stopped'} in {secs}s"
                  + (f" · {len(cached)} agents reused" if cached else ""), state=p.state, seconds=secs)
        return p

"""Cutroom Studio server: the editor UI, uploads, settings, the agent line and its live events (SSE)."""

from __future__ import annotations

import asyncio
import json
import threading
from contextlib import asynccontextmanager
from pathlib import Path

from fastapi import Body, FastAPI, File, Form, HTTPException, UploadFile
from fastapi.responses import FileResponse, Response, StreamingResponse
from fastapi.staticfiles import StaticFiles

from .. import obs
from ..config import settings
from . import line as ln
from . import skills
from .agents import BY_KEY, COLUMNS, CREW, PREP
from .agents.base import Ctx
from .agents.colorist import look_previews
from .agents.music import track_analysis
from .model import Clip, Reference, Settings, Track

WEB = Path(__file__).parent / "web"
VIDEO_EXT = {".mp4", ".mov", ".m4v", ".mkv", ".webm", ".avi", ".mts", ".mxf"}
AUDIO_EXT = {".mp3", ".wav", ".m4a", ".aac", ".flac", ".ogg"}


@asynccontextmanager
async def lifespan(_app: FastAPI):
    obs.setup(tags=["studio"])
    yield


app = FastAPI(title="Cutroom Studio", docs_url=None, redoc_url=None, lifespan=lifespan)
app.mount("/static", StaticFiles(directory=WEB), name="static")
app.mount("/fonts", StaticFiles(directory=settings.fonts_dir), name="fonts")


def _project(pid: str):
    try:
        p = ln.load(pid)
    except KeyError:
        raise HTTPException(404, "no such project")
    b = ln.bus(pid)
    if not b.events:  # after a restart, replay the recent history for the UI
        path = ln.project_dir(pid) / "events.jsonl"
        if path.exists():
            for raw in path.read_text(encoding="utf-8").splitlines()[-400:]:
                try:
                    b.emit(json.loads(raw))
                except ValueError:
                    continue
    return p


def _json(p) -> Response:
    data = json.loads(ln.dump(p))
    data["_events"] = len(ln.bus(p.id).events)
    data["_running"] = ln.run_lock(p.id).locked()
    return Response(json.dumps(data), media_type="application/json")


@app.get("/")
def index():
    return FileResponse(WEB / "index.html", headers={"Cache-Control": "no-cache"})


@app.get("/api/meta")
def meta():
    lib = []
    for t in skills.library():
        path = skills.MUSIC_DIR / t["file"]
        try:
            d = track_analysis(path)
            t |= {"tempo": d["tempo"], "duration": d["duration"]}
        except Exception:  # noqa: BLE001 - an unreadable file just shows without tempo
            pass
        lib.append(t)
    return {
        "agents": [{"key": a.key, "title": a.title, "role": a.role, "icon": a.icon, "color": a.color, "needs": list(a.needs)}
                   for a in CREW],
        "columns": COLUMNS,
        "skills": [{"name": k, **{f: v.get(f) for f in ("label", "title", "inspired", "about", "chips", "aspect")},
                    "text": v.get("text"), "pace": v.get("pace"), "custom": k not in skills.SKILLS}
                   for k, v in skills.all_skills().items()],
        "music": lib,
    }


@app.get("/api/projects")
def projects():
    return ln.list_projects()


@app.post("/api/projects")
def create(body: dict = Body(default={})):
    p = ln.new_project(body.get("name") or "untitled edit")
    return _json(p)


@app.get("/api/projects/{pid}")
def get_project(pid: str):
    return _json(_project(pid))


@app.patch("/api/projects/{pid}")
def patch_project(pid: str, body: dict = Body(...)):
    p = _project(pid)
    if "name" in body:
        p.name = str(body["name"])[:80] or p.name
    if "settings" in body:
        merged = p.settings.model_dump() | dict(body["settings"])
        new = Settings.model_validate(merged)
        if new != p.settings:
            p.hints = {}
        p.settings = new
    ln.save(p)
    return _json(p)


def _prep(pid: str) -> None:
    p = ln.load(pid)
    line = ln.Line(p, only=PREP)
    try:
        line.run()
        if p.clips and p.agents.get("intake") and p.agents["intake"].status != "failed":
            line.emit("colorist", "log", "rendering a look preview of your footage for every skill")
            ctx = Ctx(project=p, root=ln.project_dir(pid), emit=line.emit, hints={})
            p.previews = look_previews(ctx)
            ln.save(p)
            line.emit("line", "previews", "look previews ready")
    except Exception as e:  # noqa: BLE001 - reported to the UI
        line.emit("line", "fail", f"preparing footage failed: {e}")


def _start_prep(pid: str) -> None:
    threading.Thread(target=_prep, args=(pid,), daemon=True).start()


@app.post("/api/projects/{pid}/upload")
async def upload(pid: str, kind: str = Form("clip"), file: UploadFile = File(...)):
    p = _project(pid)
    root = ln.project_dir(pid)
    ext = Path(file.filename or "").suffix.lower()
    if kind in ("clip", "reference") and ext not in VIDEO_EXT:
        raise HTTPException(400, f"{ext or 'that file'} is not a video file")
    if kind == "music" and ext not in AUDIO_EXT | VIDEO_EXT:
        raise HTTPException(400, f"{ext or 'that file'} is not an audio file")
    if kind == "clip":
        n = max([int(c.id[1:]) for c in p.clips if c.id[1:].isdigit()] or [0]) + 1
        stem = f"c{n}"
    else:
        stem = kind
    dst = root / "media" / f"{stem}{ext}"
    dst.parent.mkdir(parents=True, exist_ok=True)
    with dst.open("wb") as fh:
        while chunk := await file.read(1 << 20):
            fh.write(chunk)
    name = file.filename or dst.name
    if kind == "clip":
        p.clips.append(Clip(id=stem, name=name, path=f"media/{dst.name}"))
    elif kind == "reference":
        p.reference = Reference(name=name, path=f"media/{dst.name}")
        ref_cache = root / "analysis" / "reference.json"
        ref_cache.unlink(missing_ok=True)
    else:
        p.music_upload = Track(name=Path(name).stem, path=f"media/{dst.name}", credit=f"{Path(name).stem} (your track)")
        p.settings.music = "upload"
    p.state = "preparing"
    p.hints = {}
    ln.save(p)
    _start_prep(pid)
    return _json(p)


@app.delete("/api/projects/{pid}/clips/{cid}")
def delete_clip(pid: str, cid: str):
    p = _project(pid)
    p.clips = [c for c in p.clips if c.id != cid]
    if not p.clips:
        p.state = "empty"
    ln.save(p)
    if p.clips:
        _start_prep(pid)
    return _json(p)


@app.delete("/api/projects/{pid}/reference")
def delete_reference(pid: str):
    p = _project(pid)
    p.reference = None
    ln.save(p)
    _start_prep(pid)
    return _json(p)


@app.post("/api/projects/{pid}/run")
def run(pid: str):
    p = _project(pid)
    if not p.clips:
        raise HTTPException(400, "add footage first")
    if ln.run_lock(pid).locked() and p.state == "running":
        raise HTTPException(409, "the line is already running")

    def go():
        try:
            ln.Line(ln.load(pid)).run()
        except Exception as e:  # noqa: BLE001
            ln.bus(pid).emit({"agent": "line", "kind": "fail", "msg": f"the line stopped: {e}"})

    threading.Thread(target=go, daemon=True).start()
    return {"started": True}


@app.get("/api/projects/{pid}/events")
async def events(pid: str, since: int = 0):
    _project(pid)
    b = ln.bus(pid)

    async def gen():
        i = max(0, since)
        yield "retry: 1500\n\n"
        while True:
            evs = await asyncio.to_thread(b.since, i, 15.0)
            if not evs:
                yield ": ping\n\n"
                continue
            for ev in evs:
                yield f"data: {json.dumps(ev, default=str)}\n\n"
            i += len(evs)

    return StreamingResponse(gen(), media_type="text/event-stream",
                             headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"})


@app.get("/p/{pid}/{path:path}")
def project_file(pid: str, path: str):
    root = ln.project_dir(pid).resolve()
    f = (root / path).resolve()
    if root not in f.parents or not f.is_file():
        raise HTTPException(404)
    return FileResponse(f, headers={"Cache-Control": "no-cache"})


@app.get("/music/{name}")
def music_file(name: str):
    f = (skills.MUSIC_DIR / name).resolve()
    if skills.MUSIC_DIR.resolve() not in f.parents or not f.is_file():
        raise HTTPException(404)
    return FileResponse(f)

