.mini { display: inline-flex; align-items: center; gap: 5px; height: 24px; padding: 0 8px; border-radius: 7px; border: 1px solid var(--line2); background: transparent; color: var(--text); font-size: 11.5px; font-weight: 600; letter-spacing: 0; text-transform: none; }
.mini:hover { background: var(--raise); }

.clip { display: grid; grid-template-columns: 92px 1fr; gap: 10px; padding: 6px; border-radius: 10px; position: relative; align-items: center; }
.clip:hover { background: var(--panel2); }
.cimg { width: 92px; height: 54px; border-radius: 7px; background: var(--raise2) center/cover; position: relative; overflow: hidden; }
.cimg .dur { position: absolute; right: 4px; bottom: 4px; font: 10px var(--mono); background: rgba(0,0,0,.65); padding: 1px 4px; border-radius: 4px; }
.cmeta { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.cmeta b { font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cmeta span { color: var(--mut); font-size: 11.5px; }
.badges { display: flex; gap: 4px; flex-wrap: wrap; }
.badge { font-size: 10px; padding: 1px 6px; border-radius: 20px; background: var(--raise2); color: var(--mut); white-space: nowrap; }
.badge.hot { background: color-mix(in srgb, var(--accent2) 18%, transparent); color: var(--accent2); }
.clip .x { position: absolute; right: 4px; top: 4px; opacity: 0; }
.clip:hover .x { opacity: 1; }
.bar { height: 3px; border-radius: 3px; background: var(--raise2); overflow: hidden; margin-top: 4px; }
.bar i { display: block; height: 100%; background: var(--accent); width: 0; transition: width .2s; }
.drop { border: 1.5px dashed var(--line2); border-radius: 12px; padding: 16px 14px; text-align: center; color: var(--mut); cursor: pointer; transition: .15s; display: grid; gap: 4px; justify-items: center; }
.drop:hover { border-color: var(--accent); color: var(--text); background: color-mix(in srgb, var(--accent) 6%, transparent); }
.drop b { color: var(--text); font-weight: 600; }
.drop small { font-size: 11.5px; line-height: 1.4; }
.refcard { border: 1px solid var(--line2); border-radius: 12px; overflow: hidden; background: var(--panel2); }
.refcard .rimg { height: 96px; background: var(--raise2) center/cover; position: relative; }
.refcard .rimg span { position: absolute; left: 8px; bottom: 7px; font-size: 11px; background: rgba(0,0,0,.6); padding: 2px 7px; border-radius: 20px; }
.refcard .rb { padding: 9px 10px; display: grid; gap: 7px; }
.chips { display: flex; flex-wrap: wrap; gap: 5px; }
.chip { font-size: 11px; padding: 2px 8px; border-radius: 20px; border: 1px solid var(--line2); color: var(--mut); white-space: nowrap; }
.chip.on { color: var(--text); border-color: color-mix(in srgb, var(--accent) 50%, var(--line2)); }
.tracks { display: grid; gap: 2px; max-height: 300px; overflow: auto; margin: 0 -6px; padding: 0 6px; }
.trk { display: grid; grid-template-columns: 26px 1fr auto; gap: 8px; align-items: center; padding: 5px 6px; border-radius: 8px; cursor: pointer; }
.trk:hover { background: var(--panel2); }
.trk.on { background: color-mix(in srgb, var(--accent) 11%, var(--panel2)); }
.trk .pl { width: 26px; height: 26px; border-radius: 50%; display: grid; place-items: center; border: 1px solid var(--line2); background: transparent; color: var(--mut); }
.trk .pl:hover { color: var(--text); border-color: var(--mut); }
.trk .pl svg { width: 11px; height: 11px; }
.trk b { font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.trk small { color: var(--mut); font: 10.5px var(--mono); }
.trk.on b { color: var(--text); font-weight: 600; }
.radio { width: 14px; height: 14px; border-radius: 50%; border: 1.5px solid var(--dim); display: inline-block; flex: none; }
.on > .radio, .radio.on { border: 4px solid var(--accent); }

/* ---------- viewer ---------- */
.view { grid-area: view; display: grid; grid-template-rows: 40px minmax(0, 1fr) 46px; background: radial-gradient(1200px 500px at 50% 40%, #121419, var(--bg)); min-width: 0; position: relative; }
.vtabs { display: flex; align-items: center; gap: 4px; padding: 0 12px; }
.seg { display: inline-flex; background: var(--panel); border: 1px solid var(--line); border-radius: 9px; padding: 2px; gap: 2px; }
.seg button { border: 0; background: transparent; color: var(--mut); padding: 4px 11px; border-radius: 7px; font-size: 12px; font-weight: 600; }
.seg button:hover { color: var(--text); }
.seg button.on { background: var(--raise2); color: var(--text); box-shadow: inset 0 0 0 1px var(--line2); }
.seg button:disabled { opacity: .35; pointer-events: none; }
.vinfo { margin-left: auto; color: var(--mut); font: 11.5px var(--mono); }
.stage { position: relative; display: grid; place-items: center; min-height: 0; overflow: hidden; }
.frame { position: relative; background: #000; border-radius: 6px; overflow: hidden; box-shadow: 0 30px 80px -20px rgba(0,0,0,.8), 0 0 0 1px rgba(255,255,255,.05); }
.frame video, .frame img { width: 100%; height: 100%; object-fit: contain; display: block; background: #000; }
.frame .cap { position: absolute; left: 10px; top: 10px; font-size: 11px; background: rgba(0,0,0,.6); backdrop-filter: blur(6px); padding: 3px 9px; border-radius: 20px; display: flex; align-items: center; gap: 6px; }
.frame .cap i { width: 7px; height: 7px; border-radius: 50%; background: var(--c); }
.cmp { position: absolute; inset: 0; cursor: ew-resize; }
.cmp img { position: absolute; inset: 0; }
.cmp .after { clip-path: inset(0 0 0 var(--x, 50%)); }
.cmp .handle { position: absolute; top: 0; bottom: 0; left: var(--x, 50%); width: 2px; background: #fff; transform: translateX(-1px); box-shadow: 0 0 12px rgba(0,0,0,.6); }
.cmp .handle::after { content: "⟷"; position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 30px; height: 30px; border-radius: 50%; background: #fff; color: #111; display: grid; place-items: center; font-size: 14px; }
.cmp .lb { position: absolute; bottom: 10px; font-size: 11px; padding: 2px 8px; border-radius: 20px; background: rgba(0,0,0,.6); }
.cmp .lb.l { left: 10px; } .cmp .lb.r { right: 10px; }
.empty { display: grid; place-items: center; text-align: center; gap: 10px; padding: 30px; border: 1.5px dashed var(--line2); border-radius: 18px; width: min(560px, 90%); cursor: pointer; transition: .15s; background: color-mix(in srgb, var(--panel) 60%, transparent); }
.empty:hover { border-color: var(--accent); }
.empty h2 { font: 40px/1.05 var(--serif); margin: 4px 0 0; font-weight: 400; }
.empty p { color: var(--mut); margin: 0; max-width: 420px; }
.empty .big { width: 54px; height: 54px; border-radius: 16px; display: grid; place-items: center; background: linear-gradient(135deg, var(--accent), var(--accent2)); color: #fff; }
.empty .big svg { width: 26px; height: 26px; }
.transport { display: flex; align-items: center; gap: 10px; padding: 0 14px; border-top: 1px solid var(--line); }
.play { width: 32px; height: 32px; border-radius: 50%; border: 0; background: var(--text); color: #111; display: grid; place-items: center; }
.play svg { width: 14px; height: 14px; }
.tc { font: 12.5px var(--mono); color: var(--text); min-width: 150px; }
.tc span { color: var(--dim); }
.scrub { flex: 1; height: 4px; border-radius: 4px; background: var(--raise2); position: relative; cursor: pointer; }
.scrub i { position: absolute; left: 0; top: 0; bottom: 0; background: var(--accent); border-radius: 4px; }

/* ---------- assembly line ---------- */
.line { grid-area: line; border-top: 1px solid var(--line); background: var(--bg2); display: grid; grid-template-rows: 26px 1fr; min-width: 0; }
.lhead { display: flex; align-items: center; gap: 12px; padding: 0 14px; font-size: 11.5px; color: var(--mut); white-space: nowrap; overflow: hidden; }
.lhead b { font: 600 10.5px var(--ui); letter-spacing: .14em; text-transform: uppercase; color: var(--mut); }
.lhead .lstat { margin-left: auto; font-family: var(--mono); font-size: 11px; }
.lrow { display: flex; align-items: stretch; padding: 2px 14px 10px; overflow-x: auto; overflow-y: hidden; gap: 0; }
.col { display: flex; flex-direction: column; gap: 4px; justify-content: center; flex: none; }
.col.c1 { width: 168px; } .col.c2 { width: 176px; } .col.c3 { width: 138px; }
.wire { flex: 1 1 14px; min-width: 14px; max-width: 46px; position: relative; align-self: center; height: 2px; background: var(--line2); border-radius: 2px; overflow: hidden; }
.wire.on::after { content: ""; position: absolute; top: 0; bottom: 0; width: 40%; background: linear-gradient(90deg, transparent, var(--c, var(--accent)), transparent); animation: flow 0.9s linear infinite; }
.st { position: relative; border-radius: 10px; background: var(--panel2); border: 1px solid var(--line); display: flex; gap: 8px; align-items: center; padding: 5px 8px 5px 5px; cursor: pointer; min-width: 0; transition: background .15s, border-color .15s, opacity .2s; }
.st:hover { background: var(--raise); }
.st.sel { border-color: color-mix(in srgb, var(--c) 70%, transparent); background: color-mix(in srgb, var(--c) 9%, var(--panel2)); }
.st .sic { width: 26px; height: 26px; border-radius: 7px; display: grid; place-items: center; flex: none; color: var(--c); background: color-mix(in srgb, var(--c) 16%, transparent); background-size: cover; background-position: center; overflow: hidden; }
.st .sic svg { width: 14px; height: 14px; }
.st .stx { min-width: 0; display: flex; flex-direction: column; line-height: 1.25; }
.st .stx b { font-size: 12px; font-weight: 600; white-space: nowrap; }
.st .stx span { font-size: 10.5px; color: var(--mut); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.st em { position: absolute; right: 7px; top: 5px; font: 9.5px var(--mono); color: var(--dim); font-style: normal; }
.st.s { height: 34px; }
.st.m { height: 51px; } .st.m .sic { width: 40px; height: 40px; border-radius: 8px; }
.st.l { height: 104px; flex-direction: column; align-items: stretch; padding: 5px; gap: 5px; }
.st.l .sic { width: 100%; height: 58px; border-radius: 7px; }
.st.l .sic svg { width: 20px; height: 20px; }
.st.l .stx { padding: 0 3px; }
.st.has-img .sic { background-color: #000; }
.st.has-img .sic svg { display: none; }
.st .ok { position: absolute; right: 6px; bottom: 6px; width: 14px; height: 14px; border-radius: 50%; display: grid; place-items: center; background: var(--c); color: #0b0c0e; }
.st .ok svg { width: 9px; height: 9px; stroke-width: 3.2; }
.st.is-idle, .st.is-waiting { opacity: .62; }
.st.is-skipped { opacity: .5; }
.st.is-working { border-color: transparent; background: linear-gradient(var(--panel2), var(--panel2)) padding-box, conic-gradient(from var(--ang), transparent 0 55%, var(--c) 80%, transparent 100%) border-box; border: 1px solid transparent; animation: spinb 1.4s linear infinite; }
.st.is-working .stx span { color: var(--text); }
.st.is-fixing { border-color: var(--warn); animation: blink 1s ease-in-out infinite; }
.st.is-failed { border-color: var(--bad); }
.st.is-failed .stx span { color: var(--bad); }
.st.is-cached .stx span::before { content: "reused · "; color: var(--dim); }

/* ---------- inspector ---------- */
.itabs { display: flex; gap: 2px; padding: 8px 10px 0; border-bottom: 1px solid var(--line); flex: none; }
.itabs button { border: 0; background: transparent; color: var(--mut); padding: 8px 10px 10px; font-weight: 600; font-size: 12.5px; border-bottom: 2px solid transparent; margin-bottom: -1px; }
.itabs button:hover { color: var(--text); }
.itabs button.on { color: var(--text); border-bottom-color: var(--accent); }
.ibody { overflow: auto; flex: 1; min-height: 0; padding: 4px 0 30px; }
.lead { color: var(--mut); font-size: 12px; margin: 0 0 12px; }
.skills { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.sk { position: relative; border-radius: 11px; overflow: hidden; aspect-ratio: 4 / 5; background: var(--raise2) center/cover; border: 0; padding: 0; text-align: left; box-shadow: inset 0 0 0 1px rgba(255,255,255,.06); transition: transform .15s; }
.sk:hover { transform: translateY(-1px); }
.sk::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, transparent 45%, rgba(0,0,0,.82)); }
.sk .sl { position: absolute; left: 10px; right: 10px; bottom: 9px; z-index: 1; }
.sk .sl b { display: block; font: 23px/1 var(--serif); color: #fff; }
.sk .sl span { display: block; font-size: 10px; letter-spacing: .08em; text-transform: uppercase; color: rgba(255,255,255,.72); margin-top: 3px; }
.sk.on { box-shadow: 0 0 0 2px var(--accent), 0 10px 30px -10px rgba(255,91,53,.6); }
.sk .tick { position: absolute; top: 8px; right: 8px; z-index: 1; width: 22px; height: 22px; border-radius: 50%; background: var(--accent); display: none; place-items: center; color: #fff; }
.sk.on .tick { display: grid; }
.sk .tick svg { width: 12px; height: 12px; stroke-width: 3; }
.sk.ph { background: linear-gradient(160deg, #2a2420, #15171b); }
.sk .ref { position: absolute; top: 8px; left: 8px; z-index: 1; font-size: 10px; background: var(--accent2); color: #111; padding: 1px 7px; border-radius: 20px; font-weight: 700; }
.about { margin-top: 14px; padding: 12px; border-radius: 12px; background: var(--panel2); border: 1px solid var(--line); }
.about h3 { margin: 0 0 4px; font: 26px/1.1 var(--serif); font-weight: 400; }
.about p { margin: 6px 0 10px; color: #c9c7c1; }
.about .insp-by { font-size: 11.5px; color: var(--mut); }
.recipe { display: grid; grid-template-columns: auto 1fr; gap: 4px 12px; font-size: 12px; margin-top: 10px; }
.recipe dt { color: var(--mut); }
.recipe dd { margin: 0; }
.fld { display: grid; gap: 6px; margin-bottom: 16px; }
.fld > label, .fld > .lbl { font-weight: 600; font-size: 12.5px; display: flex; justify-content: space-between; align-items: center; }
.fld > label small, .fld > .lbl small { color: var(--mut); font-weight: 400; }
.fld .hint { color: var(--mut); font-size: 11.5px; margin: -2px 0 0; }
.inp, textarea.inp { width: 100%; background: var(--bg2); border: 1px solid var(--line2); border-radius: 9px; padding: 8px 10px; color: var(--text); }
.inp:focus { outline: none; border-color: var(--accent); }
textarea.inp { resize: vertical; min-height: 110px; line-height: 1.5; }
.aspects { display: grid; grid-template-columns: repeat(5, 1fr); gap: 6px; }
.asp { border: 1px solid var(--line2); background: var(--panel2); border-radius: 10px; padding: 9px 4px 7px; display: grid; justify-items: center; gap: 6px; color: var(--mut); }
.asp:hover { color: var(--text); }
.asp .box { height: 34px; display: grid; place-items: center; }
.asp .box i { display: block; border: 1.8px solid currentColor; border-radius: 3px; }
.asp b { font: 600 11.5px var(--ui); color: var(--text); }
.asp small { font-size: 9.5px; }
.asp.on { border-color: var(--accent); color: var(--accent); background: color-mix(in srgb, var(--accent) 8%, var(--panel2)); }
.rng { display: grid; grid-template-columns: 1fr 56px; gap: 10px; align-items: center; }
.rng output { font: 12px var(--mono); text-align: right; color: var(--text); }
.rng .ends { grid-column: 1; display: flex; justify-content: space-between; font-size: 10.5px; color: var(--dim); margin-top: -4px; }
input[type=range] { -webkit-appearance: none; appearance: none; width: 100%; background: transparent; height: 18px; }
input[type=range]::-webkit-slider-runnable-track { height: 4px; border-radius: 4px; background: linear-gradient(90deg, var(--accent) var(--p, 50%), var(--raise2) var(--p, 50%)); }
input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; width: 14px; height: 14px; border-radius: 50%; background: #fff; margin-top: -5px; box-shadow: 0 1px 4px rgba(0,0,0,.6); }
.tog { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 9px 0; border-bottom: 1px solid var(--line); }
.tog div b { font-weight: 600; display: block; }
.tog div span { color: var(--mut); font-size: 11.5px; }
.sw { width: 34px; height: 20px; border-radius: 20px; background: var(--raise2); border: 1px solid var(--line2); position: relative; flex: none; padding: 0; }
.sw::after { content: ""; position: absolute; left: 2px; top: 2px; width: 14px; height: 14px; border-radius: 50%; background: var(--mut); transition: .15s; }
.sw.on { background: var(--accent); border-color: var(--accent); }
.sw.on::after { left: 16px; background: #fff; }
.card { border: 1px solid var(--line); border-radius: 12px; background: var(--panel2); padding: 12px; margin-bottom: 12px; }
.card h4 { margin: 0 0 8px; font-size: 12.5px; }
.stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.stats div { background: var(--bg2); border-radius: 9px; padding: 8px 9px; }
.stats b { display: block; font: 600 17px var(--ui); }
.stats span { color: var(--mut); font-size: 10.5px; }
.checks { display: grid; gap: 1px; }
.ck { display: grid; grid-template-columns: 18px 1fr; gap: 8px; padding: 6px 2px; border-bottom: 1px solid var(--line); font-size: 12px; }
.ck:last-child { border-bottom: 0; }
.ck i { width: 16px; height: 16px; border-radius: 50%; display: grid; place-items: center; font-style: normal; font-size: 10px; font-weight: 800; color: #0b0c0e; margin-top: 1px; }
.ck.ok i { background: var(--ok); } .ck.bad i { background: var(--bad); }
.ck b { font-weight: 600; }
.ck span { color: var(--mut); display: block; font-size: 11.5px; }
.dls { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.log { font: 11px/1.55 var(--mono); max-height: 320px; overflow: auto; background: var(--bg2); border-radius: 10px; padding: 8px 10px; border: 1px solid var(--line); }
.log div { white-space: pre-wrap; word-break: break-word; color: #b9bcc3; }
.log div b { font-weight: 600; color: var(--c); }
.log div.fail { color: var(--bad); }
.log div.decision { color: var(--text); }
.agent-h { display: flex; gap: 12px; align-items: center; margin-bottom: 10px; }
.agent-h .aic { width: 40px; height: 40px; border-radius: 11px; display: grid; place-items: center; color: var(--c); background: color-mix(in srgb, var(--c) 16%, transparent); }
.agent-h .aic svg { width: 20px; height: 20px; }
.agent-h h3 { margin: 0; font: 26px/1 var(--serif); font-weight: 400; }
.agent-h small { color: var(--mut); }
.pill { display: inline-flex; align-items: center; gap: 5px; font-size: 11px; padding: 2px 8px; border-radius: 20px; background: var(--raise2); color: var(--mut); }
.pill.working { color: var(--c); } .pill.done { color: var(--ok); } .pill.failed { color: var(--bad); } .pill.fixing { color: var(--warn); }
.decs { margin: 0; padding: 0; list-style: none; display: grid; gap: 6px; }
.decs li { padding: 8px 10px; border-radius: 9px; background: var(--bg2); border-left: 2px solid var(--c); font-size: 12px; }
.shot { border-radius: 10px; overflow: hidden; background: #000; margin: 10px 0; position: relative; }
.shot img { width: 100%; display: block; max-height: 340px; object-fit: contain; }
.back { margin: 10px 14px 0; }

/* ---------- timeline ---------- */
.tl { grid-area: tl; border-top: 1px solid var(--line); background: var(--panel); display: grid; grid-template-rows: 32px 1fr; min-width: 0; }
.tlhead { display: flex; align-items: center; gap: 14px; padding: 0 14px; border-bottom: 1px solid var(--line); white-space: nowrap; overflow: hidden; }
.tlhead b { font: 600 10.5px var(--ui); letter-spacing: .14em; text-transform: uppercase; color: var(--mut); }
.tlhead .meta { color: var(--mut); font: 11.5px var(--mono); }
.legend { display: flex; gap: 10px; margin-left: auto; font-size: 11px; color: var(--mut); }
.legend span { display: inline-flex; align-items: center; gap: 5px; }
.legend i { width: 9px; height: 9px; border-radius: 3px; background: var(--c); }
.tlbody { display: grid; grid-template-columns: 52px minmax(0, 1fr); min-height: 0; }
.tlabels { display: grid; grid-template-rows: 20px 64px 26px 1fr; border-right: 1px solid var(--line); font: 600 10px var(--mono); color: var(--dim); }
.tlabels div { display: grid; place-items: center; border-bottom: 1px solid var(--line); }
.tlscroll { overflow-x: auto; overflow-y: hidden; position: relative; }
.tlin { position: relative; height: 100%; display: grid; grid-template-rows: 20px 64px 26px 1fr; min-width: 100%; }
.ruler { position: relative; border-bottom: 1px solid var(--line); cursor: pointer; }
.ruler span { position: absolute; top: 3px; font: 9.5px var(--mono); color: var(--dim); transform: translateX(3px); }
.ruler i { position: absolute; bottom: 0; width: 1px; height: 5px; background: var(--line2); }
.ruler i.maj { height: 9px; background: #3a404a; }
.vtrack, .ttrack, .atrack { position: relative; border-bottom: 1px solid var(--line); }
.blk { position: absolute; top: 5px; bottom: 5px; border-radius: 6px; overflow: hidden; background: var(--raise2) center/cover; box-shadow: inset 0 0 0 1px rgba(255,255,255,.08); cursor: pointer; }
.blk::before { content: ""; position: absolute; left: 0; right: 0; top: 0; height: 3px; background: var(--c); }
.blk::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, transparent 40%, rgba(0,0,0,.7)); }
.blk span { position: absolute; left: 6px; bottom: 4px; z-index: 1; font: 10px var(--mono); color: #fff; white-space: nowrap; }
.blk.card { background: #050506; }
.blk.card span { color: var(--mut); }
.blk:hover { box-shadow: inset 0 0 0 1.5px #fff; }
.tr { position: absolute; top: 50%; width: 16px; height: 16px; margin-left: -8px; margin-top: -8px; z-index: 2; border-radius: 4px; transform: rotate(45deg); background: var(--accent2); box-shadow: 0 0 0 2px var(--panel); }
.txt { position: absolute; top: 4px; bottom: 4px; border-radius: 5px; background: color-mix(in srgb, #c0caf5 18%, var(--raise)); border: 1px solid color-mix(in srgb, #c0caf5 35%, transparent); font-size: 10.5px; padding: 0 6px; display: flex; align-items: center; overflow: hidden; white-space: nowrap; color: #dfe3f7; }
.txt.title, .txt.end { background: color-mix(in srgb, var(--accent2) 18%, var(--raise)); border-color: color-mix(in srgb, var(--accent2) 40%, transparent); color: #ffe2b0; }
.atrack canvas { position: absolute; left: 0; top: 0; }
.playhead { position: absolute; top: 0; bottom: 0; width: 2px; background: var(--accent); z-index: 5; pointer-events: none; transform: translateX(-1px); }
.playhead::before { content: ""; position: absolute; top: 0; left: -5px; border: 6px solid transparent; border-top-color: var(--accent); }
.tlempty { display: grid; place-items: center; color: var(--dim); font-size: 12px; height: 100%; }
.tip { position: fixed; z-index: 60; max-width: 300px; background: #1d2128; border: 1px solid var(--line2); border-radius: 9px; padding: 7px 10px; font-size: 11.5px; pointer-events: none; box-shadow: 0 10px 30px rgba(0,0,0,.5); display: none; }
.tip b { display: block; margin-bottom: 2px; }

/* drag & drop overlay */
.dz { position: fixed; inset: 0; z-index: 80; background: rgba(6,7,9,.82); backdrop-filter: blur(6px); display: none; grid-template-columns: 2fr 1fr 1fr; gap: 16px; padding: 60px; }
.dz.on { display: grid; }
.dz div { border: 2px dashed var(--line2); border-radius: 22px; display: grid; place-items: center; text-align: center; color: var(--mut); padding: 20px; transition: .12s; }
.dz div.hover { border-color: var(--accent); color: var(--text); background: color-mix(in srgb, var(--accent) 8%, transparent); }
.dz h3 { font: 34px/1.1 var(--serif); font-weight: 400; color: var(--text); margin: 6px 0; }
.toast { position: fixed; left: 50%; bottom: 236px; transform: translateX(-50%); background: #22262e; border: 1px solid var(--line2); padding: 9px 14px; border-radius: 10px; z-index: 90; font-size: 12.5px; box-shadow: 0 10px 40px rgba(0,0,0,.5); display: none; }
.toast.on { display: block; animation: rise .2s ease-out; }
.toast.bad { border-color: var(--bad); }

@keyframes rot { to { transform: rotate(360deg); } }
@keyframes spinb { to { --ang: 360deg; } }
@keyframes pulse { 50% { opacity: .35; } }
@keyframes blink { 50% { border-color: transparent; } }
@keyframes flow { from { left: -40%; } to { left: 100%; } }
@keyframes rise { from { transform: translate(-50%, 8px); opacity: 0; } }

@media (max-width: 1180px) {
  body { grid-template-columns: 236px minmax(0, 1fr) 320px; }
  .proj input { width: 140px; }
}

