const ROLE = { hook: "#ff7a59", hold: "#7aa2f7", burst: "#f7768e", outro: "#bb9af7", jump: "#e0af68", card: "#4a4f58" };
const ASPECTS = [["9:16", 9, 16, "Reels · TikTok"], ["4:5", 4, 5, "Instagram"], ["1:1", 1, 1, "Feed"], ["16:9", 16, 9, "YouTube"], ["2.39:1", 2.39, 1, "Cinema"]];

const S = { meta: null, agents: {}, p: null, pid: null, es: null, tab: "skill", station: null, view: "auto", bust: Date.now(),
  outBust: Date.now(), log: [], tick: null, uploads: [], zoom: 1, live: null, cmpX: 50, saveT: null, refreshT: null,
  running: false, viewKey: "", playingFile: null };

async function api(path, opt = {}) {
  const r = await fetch(path, { headers: { "Content-Type": "application/json" }, ...opt });
  if (!r.ok) {
    let m = r.statusText;
    try { m = (await r.json()).detail || m; } catch { /* not json */ }
    throw new Error(m);
  }
  return r.json();
}
const pf = (rel, bust = S.bust) => (rel ? `/p/${S.pid}/${rel}?v=${bust}` : "");
const fmt = (t) => `${String(Math.floor(t / 60)).padStart(2, "0")}:${(t % 60).toFixed(2).padStart(5, "0")}`;
const segLen = (g) => (g.kind === "card" ? g.card : (g.src_out - g.src_in) / (g.speed || 1));
const skillMeta = (n) => S.meta.skills.find((s) => s.name === n) || S.meta.skills[0];
const typing = () => { const a = document.activeElement; return !!(a && a.closest && a.closest("#insp") && /INPUT|TEXTAREA/.test(a.tagName)); };

function toast(msg, bad = false) {
  const t = $("#toast");
  t.textContent = msg;
  t.className = `toast on ${bad ? "bad" : ""}`;
  clearTimeout(t._t);
  t._t = setTimeout(() => (t.className = "toast"), 4200);
}

// ---------------------------------------------------------------- boot & live events
async function boot() {
  S.meta = await api("/api/meta");
  S.agents = Object.fromEntries(S.meta.agents.map((a) => [a.key, a]));
  let pid = new URL(location.href).searchParams.get("p");
  if (!pid) {
    const list = await api("/api/projects");
    pid = list[0]?.id || (await api("/api/projects", { method: "POST", body: "{}" })).id;
    history.replaceState(null, "", `?p=${pid}`);
  }
  bindGlobal();
  await openProject(pid);
}

async function openProject(pid) {
  S.pid = pid; S.station = null; S.log = []; S.live = null; S.viewKey = "";
  try {
    S.p = await api(`/api/projects/${pid}`);
  } catch {
    S.p = await api("/api/projects", { method: "POST", body: "{}" });
    S.pid = S.p.id;
    history.replaceState(null, "", `?p=${S.pid}`);
  }
  S.running = S.p._running && S.p.state === "running";
  renderAll();
  listen();
}

function listen() {
  S.es?.close();
  S.es = new EventSource(`/api/projects/${S.pid}/events?since=${Math.max(0, (S.p._events || 0) - 300)}`);
  S.es.onmessage = (e) => onEvent(JSON.parse(e.data));
}

function onEvent(ev) {
  const agents = (S.p.agents ||= {});
  const a = ev.agent && S.agents[ev.agent] ? (agents[ev.agent] ||= { key: ev.agent, decisions: [], checks: [] }) : null;
  if (ev.kind === "status" && a) {
    Object.assign(a, { status: ev.status, summary: ev.summary || "", preview: ev.preview || "", before: ev.before || "", seconds: ev.seconds || 0 });
    if (ev.status === "working") { a.decisions = []; a.checks = []; setTick(ev.agent, "working…"); }
    if (ev.status === "done" && ev.preview) { S.bust = Date.now(); S.live = { agent: ev.agent, img: ev.preview, t: S.bust }; }
    renderLine();
    if (S.station === ev.agent) renderInsp();
    if (S.running) renderViewer();
    if (["done", "cached", "skipped", "failed"].includes(ev.status)) refreshSoon();
  } else if (ev.kind === "decision" && a) {
    (a.decisions ||= []).push(ev.msg);
    setTick(ev.agent, ev.msg);
    if (S.station === ev.agent) renderInsp();
  } else if (ev.kind === "check" && a) {
    (a.checks ||= []).push({ name: ev.name, ok: ev.ok, detail: ev.msg.slice(ev.msg.indexOf(": ") + 2) });
    if (S.station === ev.agent) renderInsp();
  } else if (ev.kind === "sendback") {
    setTick("qa", ev.msg);
  } else if (ev.kind === "fail") {
    setTick(ev.agent, ev.msg);
  } else if (ev.kind === "line") {
    S.running = ev.state === "running";
    if (ev.state) S.p.state = ev.state;
    if (S.running) S.live = null;
    setTick("line", ev.msg);
    renderTop();
    refreshSoon(60);
  } else if (ev.kind === "previews") {
    refreshSoon(60);
  }
  if (ev.kind !== "status" && ev.kind !== "progress") {
    S.log.push(ev);
    if (S.log.length > 600) S.log.shift();
    if (S.tab === "report" && !S.station) appendLog(ev);
  }
}

function refreshSoon(ms = 400) {
  clearTimeout(S.refreshT);
  S.refreshT = setTimeout(async () => {
    try {
      const p = await api(`/api/projects/${S.pid}`);
      if (p.outputs?.bytes !== S.p.outputs?.bytes) S.outBust = Date.now();
      S.p = p;
      S.running = p._running && p.state === "running";
      renderAll();
    } catch { /* offline for a moment */ }
  }, ms);
}

function setTick(agent, msg) { S.tick = { agent, msg }; renderTicker(); }

// ---------------------------------------------------------------- top bar
function renderTop() {
  const p = S.p, done = !!p.outputs?.video;
  $("#top").innerHTML = `
    <div class="brand"><span class="mark"></span><span class="word">cutroom</span><span class="tag">studio</span></div>
    <div class="proj"><input id="pname" value="${esc(p.name)}" spellcheck="false" aria-label="Project name">
      <button class="iconbtn" data-act="projects" title="Your edits">${I.chev}</button><div class="menu" id="menu"></div></div>
    <div class="ticker" id="ticker"></div>
    <div class="acts">
      <button class="btn" data-act="new">${I.plus} New edit</button>
      <a class="btn" ${done ? `href="${pf(p.outputs.video, S.outBust)}" download="${esc(p.name)}.mp4"` : 'aria-disabled="true"'}>${I.download} Export MP4</a>
      <button class="btn run ${S.running ? "busy" : ""}" data-act="run" ${p.clips.length ? "" : "disabled"}>
        <span class="spin"></span>${S.running ? "Line running…" : `${I.play} Run the line`}</button>
    </div>`;
  renderTicker();
}

function renderTicker() {
  const el = $("#ticker");
  if (!el) return;
  const t = S.tick;
  if (!t) {
    const p = S.p;
    const msg = !p.clips.length ? "Drop raw footage to start. Pick a skill, tell the story, run the line."
      : p.outputs?.video ? `Delivered ${p.outputs.width}×${p.outputs.height} · ${(+p.outputs.duration).toFixed(1)}s. Change anything and run again; unchanged work is reused.`
      : "Footage measured. Pick a skill and run the line.";
    el.className = "ticker";
    el.innerHTML = `<span class="tdot"></span><span class="msg">${esc(msg)}</span>`;
    return;
  }
  const m = S.agents[t.agent];
  el.className = `ticker ${S.running ? "live" : ""}`;
  el.style.setProperty("--c", m?.color || "var(--accent)");
  el.innerHTML = `<span class="tdot"></span><b>${esc(m?.title || "Line")}</b><span class="msg">${esc(t.msg)}</span>`;
}

// ---------------------------------------------------------------- media bin
function renderBin() {
  const p = S.p;
  const clips = p.clips.map((c) => `
    <div class="clip">
      <div class="cimg" style="${c.poster ? `background-image:url('${pf(c.poster, 1)}')` : ""}">${c.duration ? `<span class="dur">${c.duration.toFixed(1)}s</span>` : ""}</div>
      <div class="cmeta"><b title="${esc(c.name)}">${esc(c.name)}</b>
        <span>${c.width ? `${c.width}×${c.height} · ${+c.fps.toFixed(2)} fps` : "measuring…"}</span>
        <span class="badges">${c.flat ? '<i class="badge hot">flat colour</i>' : ""}${c.width && !c.has_audio ? '<i class="badge">silent</i>' : ""}${c.cuts?.length ? `<i class="badge">${c.cuts.length} cuts</i>` : ""}${c.sound?.length ? `<i class="badge">${c.sound.length} sounds</i>` : ""}</span></div>
      <button class="iconbtn x" data-act="del-clip" data-id="${c.id}" title="Remove clip">${I.x}</button>
    </div>`).join("");
  const ups = S.uploads.map((u) => `
    <div class="clip"><div class="cimg"></div><div class="cmeta"><b>${esc(u.name)}</b><span>uploading ${u.pct}% · ${u.kind}</span><div class="bar"><i style="width:${u.pct}%"></i></div></div></div>`).join("");
  const r = p.reference, prof = r?.profile;
  const ref = r ? `
    <div class="refcard"><div class="rimg" style="${r.poster ? `background-image:url('${pf(r.poster, 1)}')` : ""}"><span>${esc(r.name)}</span></div>
      <div class="rb">${prof?.shots ? `<div class="chips">${refChips(prof).map((c) => `<span class="chip on">${esc(c)}</span>`).join("")}</div>` : '<span class="lead" style="margin:0">The Reference agent is watching it…</span>'}
        <div style="display:flex;gap:6px"><button class="mini" data-act="tab" data-tab="skill">Edit like it</button><button class="mini" data-act="del-ref">Remove</button></div></div></div>`
    : `<div class="drop" data-act="pick" data-kind="reference">${I.eye}<b>Add a reference video</b><small>A video you want your edit to feel like. The Reference agent watches it first and measures its rhythm, colour, grain and beat sync.</small></div>`;
  const def = skillMeta(p.settings.skill).music;
  const cur = p.settings.music;
  const row = (val, title, sub, file) => `
    <div class="trk ${cur === val ? "on" : ""}" data-act="music" data-val='${esc(JSON.stringify(val))}'>
      ${file ? `<button class="pl" data-act="listen" data-file="${esc(file)}" title="Listen">${S.playingFile === file ? I.pause : I.play}</button>` : `<span class="radio ${cur === val ? "on" : ""}" style="margin-left:6px"></span>`}
      <b>${esc(title)}</b><small>${esc(sub || "")}</small></div>`;
  const lib = S.meta.music.map((m) => row(`library:${m.file}`, m.title, m.tempo ? `${Math.round(m.tempo)} bpm` : "", m.file)).join("");
  $("#bin").innerHTML = `
    <div class="sec"><div class="sh"><span>Footage</span><button class="mini" data-act="pick" data-kind="clip">${I.plus} Add</button></div>
      ${clips || ups ? clips + ups : `<div class="drop" data-act="pick" data-kind="clip">${I.film}<b>Add raw footage</b><small>Drop clips anywhere. Any length, any resolution, log or flat colour is fine.</small></div>`}
    </div>
    <div class="sec"><div class="sh"><span>Reference</span></div>${ref}</div>
    <div class="sec"><div class="sh"><span>Music</span><button class="mini" data-act="pick" data-kind="music">${I.upload} Yours</button></div>
      <div class="tracks">
        ${row(null, `Skill default${def ? ` · ${def.replace(/_/g, " ").replace(/\.mp3$/, "")}` : " · none"}`, "")}
        ${row("none", "No music", "footage sound only")}
        ${p.music_upload ? row("upload", p.music_upload.name, "your track") : ""}
        ${lib}
      </div>
      <p class="lead" style="margin:8px 0 0;font-size:11px">Library tracks by Kevin MacLeod (incompetech.com), CC BY 4.0. The credit is written into every export.</p>
    </div>`;
}

function refChips(prof) {
  const s = prof.shots, lab = prof.look.lab_mean;
  const out = [`median shot ${s.median}s`, `${s.cuts_per_min} cuts/min`, lab[2] > 8 ? "warm" : lab[2] < -2 ? "cool" : "neutral colour", `grain ${prof.noise}`];
  if (prof.letterbox) out.push(`${prof.letterbox}:1 letterbox`);
  if (prof.tempo) out.push(`${Math.round(prof.tempo)} bpm · ${Math.round(prof.on_beat * 100)}% cuts on beat`);
  return out;
}

// ---------------------------------------------------------------- viewer
function viewMode() {
  const p = S.p, col = p.agents?.colorist || {};
  const has = { output: !!p.outputs?.video, compare: !!(col.before && col.preview), footage: p.clips.some((c) => c.poster) };
  let v = S.view;
  if (v === "auto") v = S.running && S.live ? "live" : has.output ? "output" : has.compare ? "compare" : has.footage ? "footage" : "empty";
  if (!["live", "empty"].includes(v) && !has[v]) v = has.output ? "output" : has.footage ? "footage" : p.clips.length ? "footage" : "empty";
  if (!p.clips.length && !S.uploads.length) v = "empty";
  return [v, has];
}

function renderViewer(force = false) {
  const [v, has] = viewMode();
  const p = S.p, o = p.outputs || {};
  const key = `${v}|${v === "output" ? S.outBust : ""}|${v === "live" ? S.live?.t : ""}|${v === "compare" ? S.bust : ""}|${p.settings.aspect}|${p.clips.length}`;
  if (!force && key === S.viewKey) return;
  S.viewKey = key;
  const tabs = `<div class="seg">
      <button class="${v === "output" ? "on" : ""}" data-act="view" data-v="output" ${has.output ? "" : "disabled"}>Output</button>
      <button class="${v === "compare" ? "on" : ""}" data-act="view" data-v="compare" ${has.compare ? "" : "disabled"}>Before / after</button>
      <button class="${v === "footage" ? "on" : ""}" data-act="view" data-v="footage" ${has.footage ? "" : "disabled"}>Footage</button>
      ${S.running ? `<button class="${v === "live" ? "on" : ""}" data-act="view" data-v="auto">Live</button>` : ""}</div>
    <span class="vinfo">${has.output ? `${o.width}×${o.height} · ${o.fps} fps · ${(+o.duration).toFixed(1)}s · ${(o.bytes / 1e6).toFixed(1)} MB` : ""}</span>`;
  let stage = "", ar = 9 / 16;
  const [aw, ah] = (ASPECTS.find((x) => x[0] === p.settings.aspect) || ASPECTS[0]).slice(1, 3);
  const outAr = p.settings.aspect === "2.39:1" ? 16 / 9 : aw / ah;
  if (v === "empty") {
    stage = `<div class="empty" data-act="pick" data-kind="clip"><div class="big">${I.upload}</div><h2>Drop your raw footage</h2>
      <p>Eleven agents, each with one job, edit it in the skill you pick: intake, reference, music, colorist, cutter, reframer, motion, typographer, mixer, export, QA.</p>
      <p style="font-size:12px">or click to choose files · add a reference video to edit like it</p></div>`;
  } else if (v === "output") {
    ar = o.width / o.height;
    stage = `<div class="frame" data-ar="${ar}"><video id="vid" src="${pf(o.video, S.outBust)}" poster="${pf(o.poster, S.outBust)}" playsinline preload="auto"></video></div>`;
  } else if (v === "compare") {
    const col = p.agents.colorist;
    ar = outAr;
    stage = `<div class="frame" data-ar="${ar}"><div class="cmp" id="cmp" style="--x:${S.cmpX}%">
      <img src="${pf(col.before)}" alt="before"><img class="after" src="${pf(col.preview)}" alt="after">
      <span class="handle"></span><span class="lb l">camera original</span><span class="lb r">colorist · ${esc(skillMeta(p.settings.skill).label)}</span></div></div>`;
  } else if (v === "live") {
    const m = S.agents[S.live.agent];
    stage = `<div class="frame" data-ar="${outAr}"><img src="${pf(S.live.img, S.live.t)}" data-fit="1" alt="">
      <span class="cap" style="--c:${m.color}"><i></i>after ${esc(m.title)}</span></div>`;
  } else {
    const c = p.clips.find((x) => x.poster) || p.clips[0];
    ar = c.width && c.height ? c.width / c.height : 16 / 9;
    stage = `<div class="frame" data-ar="${ar}">${c.poster ? `<img src="${pf(c.poster, 1)}" alt="">` : ""}<span class="cap" style="--c:#7aa2f7"><i></i>${esc(c.name)} · camera original</span></div>`;
  }
  $("#view").innerHTML = `<div class="vtabs">${tabs}</div><div class="stage" id="stage">${stage}</div>
    <div class="transport">${v === "output" ? `<button class="play" data-act="play" id="playbtn">${I.play}</button>
      <span class="tc" id="tc">00:00.00 <span>/ ${fmt(+o.duration || 0)}</span></span>
      <div class="scrub" id="scrub"><i id="scrubi"></i></div>
      <button class="iconbtn" data-act="mute" id="mutebtn" title="Mute">${I.vol}</button>
      <button class="iconbtn" data-act="full" title="Full screen">${I.full}</button>`
      : `<span class="lead" style="margin:0">${v === "compare" ? "Drag across the frame to compare the camera original with the Colorist's grade." : v === "live" ? "Each agent's output appears here as the edit moves down the line." : v === "footage" ? "Run the line to edit this footage." : ""}</span>`}</div>`;
  fitFrame();
  const img = $("#stage img[data-fit]");
  if (img) img.onload = () => { $(".frame").dataset.ar = img.naturalWidth / img.naturalHeight; fitFrame(); };
  const vid = $("#vid");
  if (vid) bindVideo(vid);
}

function fitFrame() {
  const st = $("#stage"), fr = st && $(".frame", st);
  if (!fr) return;
  const ar = +fr.dataset.ar || 9 / 16;
  const W = st.clientWidth - 40, H = st.clientHeight - 26;
  let w = W, h = w / ar;
  if (h > H) { h = H; w = h * ar; }
  fr.style.width = `${Math.max(40, w)}px`;
  fr.style.height = `${Math.max(40, h)}px`;
}

function bindVideo(vid) {
  const upd = () => {
    const t = vid.currentTime, d = vid.duration || +S.p.outputs.duration || 1;
    const tc = $("#tc");
    if (tc) tc.innerHTML = `${fmt(t)} <span>/ ${fmt(d)}</span>`;
    const si = $("#scrubi");
    if (si) si.style.width = `${(t / d) * 100}%`;
    movePlayhead(t);
  };
  const loop = () => { upd(); if (!vid.paused) requestAnimationFrame(loop); };
  vid.addEventListener("play", () => { $("#playbtn").innerHTML = I.pause; loop(); });
  vid.addEventListener("pause", () => { $("#playbtn").innerHTML = I.play; upd(); });
  vid.addEventListener("seeked", upd);
  vid.addEventListener("click", () => (vid.paused ? vid.play() : vid.pause()));
  $("#scrub").addEventListener("pointerdown", (e) => {
    const r = e.currentTarget.getBoundingClientRect();
    vid.currentTime = clamp((e.clientX - r.left) / r.width, 0, 1) * (vid.duration || 0);
  });
}

function seek(t) {
  const vid = $("#vid");
  if (vid) vid.currentTime = t;
  movePlayhead(t);
}

// ---------------------------------------------------------------- assembly line
function renderLine() {
  const last = S.p.runs?.at(-1);
  let html = `<div class="lhead"><b>Assembly line</b><span>${S.meta.agents.length} agents, one job each · agents in a column work at the same time · no model in the edit path: same footage + same choices = same edit</span>
    <span class="lstat">${last ? `last run ${last.seconds}s · ${last.cached.length} agent${last.cached.length === 1 ? "" : "s"} reused${last.loops ? ` · ${last.loops} QA round${last.loops > 1 ? "s" : ""}` : ""}` : ""}</span></div><div class="lrow">`;
  S.meta.columns.forEach((col, ci) => {
    if (ci) {
      const on = col.some((k) => S.p.agents?.[k]?.status === "working");
      html += `<div class="wire ${on ? "on" : ""}" style="--c:${S.agents[col[0]].color}"></div>`;
    }
    const size = col.length >= 3 ? "s" : col.length === 2 ? "m" : "l";
    html += `<div class="col ${size === "s" ? "c1" : size === "m" ? "c2" : "c3"}">${col.map((k) => station(k, size)).join("")}</div>`;
  });
  $("#line").innerHTML = `${html}</div>`;
}

function station(k, size) {
  const m = S.agents[k], a = S.p.agents?.[k] || {}, st = a.status || "idle";
  const img = a.preview && ["done", "cached"].includes(st) && size !== "s" ? pf(a.preview) : "";
  const txt = { idle: "idle", waiting: "waiting", working: "working…", failed: a.summary || "failed", fixing: "fixing · sent back by QA" }[st] ?? (a.summary || st);
  return `<div class="st ${size} is-${st} ${img ? "has-img" : ""} ${S.station === k ? "sel" : ""}" data-act="station" data-key="${k}" style="--c:${m.color}" title="${esc(m.title)}: ${esc(m.role)}">
    <div class="sic" ${img ? `style="background-image:url('${img}')"` : ""}>${I[m.icon] || ""}</div>
    <div class="stx"><b>${esc(m.title)}</b><span>${esc(txt)}</span></div>
    ${a.seconds && ["done", "failed"].includes(st) && size !== "s" ? `<em>${a.seconds < 10 ? a.seconds.toFixed(1) : Math.round(a.seconds)}s</em>` : ""}
    ${["done", "cached"].includes(st) ? `<span class="ok">${I.check}</span>` : ""}</div>`;
}

// ---------------------------------------------------------------- inspector
function renderInsp() {
  const body = $("#ibody");
  const keep = body ? body.scrollTop : 0;
  if (S.station) { renderAgent(); return; }
  const tabs = [["skill", "Skill"], ["format", "Format"], ["story", "Story"], ["tune", "Tune"], ["report", "Report"]];
  const fn = { skill: tabSkill, format: tabFormat, story: tabStory, tune: tabTune, report: tabReport }[S.tab];
  $("#insp").innerHTML = `<div class="itabs">${tabs.map(([k, l]) => `<button class="${S.tab === k ? "on" : ""}" data-act="tab" data-tab="${k}">${l}</button>`).join("")}</div>
    <div class="ibody" id="ibody">${fn()}</div>`;
  paintRanges();
  $("#ibody").scrollTop = keep;
  const log = $("#log");
  if (log) log.scrollTop = log.scrollHeight;
}

function tabSkill() {
  const p = S.p, cur = p.settings.skill, ref = p.reference?.profile?.shots ? p.reference : null;
  const cards = S.meta.skills.map((s) => {
    const img = p.previews?.[s.name];
    return `<button class="sk ${img ? "" : "ph"} ${cur === s.name ? "on" : ""}" data-act="set" data-key="skill" data-v='"${s.name}"' style="${img ? `background-image:url('${pf(img)}')` : ""}">
      <span class="tick">${I.check}</span><span class="sl"><b>${esc(s.label)}</b><span>${esc(s.title)}</span></span></button>`;
  }).join("");
  const refBlock = ref ? `<div class="card"><div class="tog" style="padding-top:0"><div><b>Edit like the reference</b><span>${esc(ref.name)}: rhythm, colour, grain, framing${ref.profile.tempo ? ", beat sync" : ""}</span></div>
      <button class="sw ${p.settings.match_reference ? "on" : ""}" data-act="toggle" data-key="match_reference"></button></div>
      ${p.settings.match_reference ? rangeField("reference_strength", "Match strength", 0.2, 1, 0.05, (v) => `${Math.round(v * 100)}%`, ["skill", "reference"]) : ""}
      ${p.previews?.reference ? `<div class="shot" style="margin-bottom:0"><img src="${pf(p.previews.reference)}" alt="your footage in the reference's colour"></div>` : ""}</div>` : "";
  return `<div class="sec">${refBlock}<p class="lead">Each skill is a recipe the agents follow: pacing, colour, moves, type and sound. No model, no prompt. Pick one, then tune it. The stills are your own footage in each look.</p>
    <div class="skills">${cards}</div>${about(skillMeta(cur))}</div>`;
}

function about(s) {
  const pace = s.pace || {}, t = s.text || {};
  const caseTxt = t.case === "lower" ? "lowercase" : t.case === "upper" ? "capitals" : "as typed";
  return `<div class="about"><h3>${esc(s.label)}</h3><div class="insp-by">${esc(s.title)} · inspired by ${esc(s.inspired)}</div>
    <p>${esc(s.about)}</p><div class="chips">${(s.chips || []).map((c) => `<span class="chip on">${esc(c)}</span>`).join("")}</div>
    <dl class="recipe">
      <dt>Rhythm</dt><dd>${pace.jumpcut ? "every pause cut out, jump cuts" : `holds of ~${pace.shot}s${pace.burst_every ? `, bursts of ${pace.burst_len} quick cuts` : ""}`}</dd>
      <dt>Order</dt><dd>${pace.order === "energy" ? "strongest moments on the loudest beats" : "story order"}</dd>
      <dt>Type</dt><dd>${esc(t.story?.font || "")}, ${caseTxt}${t.title?.card ? "; title card on black" : ""}</dd>
      <dt>Music</dt><dd>${esc(s.music ? s.music.replace(/_/g, " ").replace(/\.mp3$/, "") : "none (footage sound)")}</dd>
      <dt>Made for</dt><dd>${esc(s.aspect)}</dd></dl></div>`;
}

function segOpts(key, opts, cur) {
  return `<div class="seg">${opts.map(([v, l]) => `<button class="${JSON.stringify(cur) === JSON.stringify(v) ? "on" : ""}" data-act="set" data-key="${key}" data-v='${esc(JSON.stringify(v))}'>${esc(l)}</button>`).join("")}</div>`;
}

function rangeField(key, label, min, max, step, show, ends) {
  const v = S.p.settings[key];
  return `<div class="fld"><div class="lbl">${esc(label)}</div><div class="rng">
    <input type="range" min="${min}" max="${max}" step="${step}" value="${v}" data-set="${key}" data-kind="num" data-show="${key}">
    <output id="o-${key}">${show(v)}</output>${ends ? `<div class="ends"><span>${ends[0]}</span><span>${ends[1]}</span></div>` : ""}</div></div>`;
}
const SHOW = {
  pacing: (v) => `×${(+v).toFixed(2)}`, look: (v) => `${Math.round(v * 100)}%`, grain: (v) => (+v).toFixed(1),
  music_level: (v) => `${v > 0 ? "+" : ""}${v} dB`, ambient: (v) => `${v} dB`, length: (v) => `${v}s`,
  reference_strength: (v) => `${Math.round(v * 100)}%`,
};

function tabFormat() {
  const s = S.p.settings;
  const asp = ASPECTS.map(([k, w, h, l]) => {
    const sc = 30 / Math.max(w, h);
    return `<button class="asp ${s.aspect === k ? "on" : ""}" data-act="set" data-key="aspect" data-v='"${k}"'><span class="box"><i style="width:${Math.round(w * sc)}px;height:${Math.round(h * sc)}px"></i></span><b>${k}</b><small>${l}</small></button>`;
  }).join("");
  const auto = s.length == null;
  return `<div class="sec">
    <div class="fld"><div class="lbl">Format</div><div class="aspects">${asp}</div>
      <p class="hint">The Reframer crops each shot to this frame and keeps the subject in it; narrower footage gets a blurred fill instead of a crop.</p></div>
    <div class="fld"><div class="lbl">Resolution</div>${segOpts("resolution", [[720, "720p"], [1080, "1080p"], [2160, "4K"]], s.resolution)}</div>
    <div class="fld"><div class="lbl">Frame rate</div>${segOpts("fps", [[null, "Footage"], [24, "24"], [25, "25"], [30, "30"], [60, "60"]], s.fps)}</div>
    <div class="fld"><div class="lbl">Length <small>${auto ? "decided from your footage and the skill" : ""}</small></div>
      ${segOpts("length", [[null, "Auto"], [15, "15s"], [30, "30s"], [60, "60s"]], [null, 15, 30, 60].includes(s.length) ? s.length : "custom")}
      ${auto ? "" : `<div class="rng" style="margin-top:6px"><input type="range" min="5" max="120" step="1" value="${s.length}" data-set="length" data-kind="num" data-show="length"><output id="o-length">${s.length}s</output></div>`}
      <p class="hint">With music, the length snaps to the beat so the last cut lands on one.</p></div></div>`;
}

function tabStory() {
  const s = S.p.settings, sk = skillMeta(s.skill), t = sk.text || {};
  return `<div class="sec"><p class="lead">The Typographer sets these in ${esc(sk.label)}'s type, on the cuts, each long enough to read, and shades any line that sits on a bright background.</p>
    <div class="fld"><label>Title <small>${t.title?.card ? "a card on black before the first shot" : "over the opening shot"}</small></label>
      <input class="inp" data-set="title" value="${esc(s.title)}" placeholder="episode 1. the coast"></div>
    <div class="fld"><label>Time / place stamp <small>on the first shot</small></label>
      <input class="inp" data-set="stamp" value="${esc(s.stamp)}" placeholder="7:28pm."></div>
    <div class="fld"><label>Story lines <small>one per line, in order</small></label>
      <textarea class="inp" data-set="story" data-kind="lines" placeholder="i woke up before the alarm.&#10;the city was still asleep.&#10;so i went looking for the sea.">${esc((s.story || []).join("\n"))}</textarea></div>
    <div class="fld"><label>End card <small>${t.end?.card ? "on black after the last shot" : "over the last shot"}</small></label>
      <input class="inp" data-set="end_card" value="${esc(s.end_card)}" placeholder="fin."></div>
    <div class="fld"><div class="lbl">Letter case</div>${segOpts("lowercase", [[null, "Skill default"], [true, "lowercase"], [false, "As typed"]], s.lowercase)}</div></div>`;
}

function tabTune() {
  const s = S.p.settings;
  const tog = (k, title, sub) => `<div class="tog"><div><b>${title}</b><span>${sub}</span></div><button class="sw ${s[k] ? "on" : ""}" data-act="toggle" data-key="${k}"></button></div>`;
  return `<div class="sec">
    ${rangeField("pacing", "Pacing", 0.6, 1.6, 0.05, SHOW.pacing, ["slower holds", "faster cuts"])}
    ${rangeField("look", "Look strength", 0, 1.5, 0.05, SHOW.look, ["natural", "strong"])}
    <div class="fld"><div class="lbl">Film grain</div>${segOpts("grain", [[null, "Skill"], [0, "None"], [4, "Fine"], [9, "Film"], [16, "Heavy"]], s.grain)}</div>
    ${rangeField("music_level", "Music level", -12, 6, 1, SHOW.music_level, ["quieter", "louder"])}
    <div class="fld"><div class="lbl">Footage sound</div>${segOpts("ambient", [[null, "Skill"], [-60, "Off"], [-20, "Low"], [-10, "Mid"], [0, "Full"]], s.ambient)}</div>
    ${tog("beat_sync", "Cut on the beat", "Every cut lands on a beat of the music")}
    ${tog("transitions", "Transitions", "Whips, dissolves, flashes and dips the skill uses")}
    ${tog("slowmo", "Slow motion", "Only where the footage's frame rate allows it")}</div>`;
}

function tabReport() {
  const p = S.p, o = p.outputs || {}, last = p.runs?.at(-1), qa = p.qa || [];
  const fails = qa.filter((c) => !c.ok).length;
  const deliver = o.video ? `<div class="card"><h4>Delivered</h4><div class="stats">
      <div><b>${(+o.duration).toFixed(1)}s</b><span>${o.width}×${o.height} · ${o.fps} fps</span></div>
      <div><b>${last ? `${last.seconds}s` : "–"}</b><span>line time</span></div>
      <div><b>${last ? `${last.ran.length}/${S.meta.agents.length}` : "–"}</b><span>agents ran (${last ? last.cached.length : 0} reused)</span></div></div>
      <div class="dls"><a class="mini" href="${pf(o.video, S.outBust)}" download>${I.download} MP4</a><a class="mini" href="${pf(o.edl, S.outBust)}" download>EDL · Premiere / Resolve</a>
        <a class="mini" href="${pf(o.json, S.outBust)}" download>Edit JSON</a><a class="mini" href="${pf(o.poster, S.outBust)}" download>Poster</a></div>
      ${o.credit ? `<p class="lead" style="margin:10px 0 0">Music: ${esc(o.credit)}</p>` : ""}</div>` : `<div class="card"><h4>Nothing delivered yet</h4><p class="lead" style="margin:0">Run the line: the Export agent renders, then QA measures the result.</p></div>`;
  const checks = qa.length ? `<div class="card"><h4>QA · ${fails ? `${fails} failing` : "every check passes"}${p.loops ? ` · ${p.loops} round${p.loops > 1 ? "s" : ""} of fixes` : ""}</h4><div class="checks">
      ${qa.map((c) => `<div class="ck ${c.ok ? "ok" : "bad"}"><i>${c.ok ? "✓" : "!"}</i><div><b>${esc(c.name)}</b><span>${esc(c.detail)}${c.ok ? "" : ` · owner: ${esc(S.agents[c.owner]?.title || c.owner)}`}</span></div></div>`).join("")}</div></div>` : "";
  const trace = p.trace_id ? `<div class="card"><h4>Trace</h4><p class="lead" style="margin:0">Every agent is a span in neatlogs (workflow <code>studio.line</code>). Trace id <code style="color:var(--text)">${esc(p.trace_id)}</code></p></div>` : "";
  const runs = p.runs?.length ? `<div class="card"><h4>Runs</h4>${p.runs.slice(-5).reverse().map((r) => `<div class="ck ${r.ok ? "ok" : "bad"}"><i>${r.ok ? "✓" : "!"}</i><div><b>${new Date(r.at * 1000).toLocaleTimeString()} · ${esc(r.skill)} · ${r.seconds}s</b><span>${r.ran.length} ran · ${r.cached.length} reused${r.loops ? ` · ${r.loops} QA rounds` : ""}</span></div></div>`).join("")}</div>` : "";
  return `<div class="sec">${deliver}${checks}${trace}${runs}<div class="sh" style="margin-top:6px"><span>Activity</span></div><div class="log" id="log">${S.log.slice(-250).map(logRow).join("")}</div></div>`;
}

function logRow(ev) {
  const m = S.agents[ev.agent];
  return `<div class="${ev.kind}" style="--c:${m?.color || "var(--accent)"}"><b>${esc(m?.title || "line")}</b> ${esc(ev.msg)}</div>`;
}
function appendLog(ev) {
  const log = $("#log");
  if (!log) return;
  const stick = log.scrollTop + log.clientHeight >= log.scrollHeight - 30;
  log.insertAdjacentHTML("beforeend", logRow(ev));
  if (stick) log.scrollTop = log.scrollHeight;
}

function renderAgent() {
  const k = S.station, m = S.agents[k], a = S.p.agents?.[k] || {};
  const st = a.status || "idle";
  const needs = m.needs.map((n) => S.agents[n].title);
  const imgs = a.before && a.preview
    ? `<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px"><div class="shot"><img src="${pf(a.before)}" alt="before"><span class="cap" style="position:absolute;left:6px;top:6px;font-size:10px;background:rgba(0,0,0,.6);padding:1px 6px;border-radius:9px">before</span></div><div class="shot"><img src="${pf(a.preview)}" alt="after"><span class="cap" style="position:absolute;left:6px;top:6px;font-size:10px;background:rgba(0,0,0,.6);padding:1px 6px;border-radius:9px">after</span></div></div>`
    : a.preview ? `<div class="shot"><img src="${pf(a.preview)}" alt=""></div>` : "";
  $("#insp").innerHTML = `<div class="itabs"><button class="on" data-act="back" style="display:flex;gap:4px;align-items:center">${I.back} All settings</button></div>
    <div class="ibody" id="ibody"><div class="sec" style="--c:${m.color}">
      <div class="agent-h"><div class="aic">${I[m.icon]}</div><div><h3>${esc(m.title)}</h3><small>${needs.length ? `works after ${esc(needs.join(", "))}` : "starts first"}</small></div></div>
      <p style="margin:0 0 10px;color:#cfccc5">${esc(m.role)}.</p>
      <span class="pill ${st}">${st}${a.seconds ? ` · ${a.seconds}s` : ""}</span>
      ${a.summary ? `<p class="lead" style="margin:10px 0 0">${esc(a.summary)}</p>` : ""}
      ${imgs}
      ${(a.decisions || []).length ? `<div class="sh" style="margin-top:14px"><span>Decisions</span></div><ul class="decs">${a.decisions.map((d) => `<li>${esc(d)}</li>`).join("")}</ul>` : ""}
      ${(a.checks || []).length ? `<div class="sh" style="margin-top:14px"><span>Self-checks</span></div><div class="checks">${a.checks.map((c) => `<div class="ck ${c.ok ? "ok" : "bad"}"><i>${c.ok ? "✓" : "!"}</i><div><b>${esc(c.name)}</b><span>${esc(c.detail)}</span></div></div>`).join("")}</div>` : ""}
      ${st === "idle" ? '<p class="lead" style="margin-top:12px">Run the line to see what this agent decides for your footage.</p>' : ""}
    </div></div>`;
}

function paintRanges() {
  document.querySelectorAll("input[type=range]").forEach((r) => {
    const p = ((r.value - r.min) / (r.max - r.min)) * 100;
    r.style.setProperty("--p", `${p}%`);
  });
}

// ---------------------------------------------------------------- timeline
function renderTL() {
  const p = S.p, tl = p.timeline || [];
  const dur = tl.length ? tl.at(-1).start + segLen(tl.at(-1)) : 0;
  const tr = p.track;
  const head = `<div class="tlhead"><b>Timeline</b><span class="meta">${tl.length ? `${dur.toFixed(2)}s · ${tl.filter((g) => g.kind === "clip").length} shots · ${(p.texts || []).length} text events${tr ? ` · ${esc(tr.name)} ${Math.round(tr.tempo)} bpm` : ""}` : ""}</span>
    <div class="legend">${Object.entries(ROLE).map(([k, c]) => `<span style="--c:${c}"><i></i>${k}</span>`).join("")}<span style="--c:var(--accent2)"><i style="transform:rotate(45deg)"></i>transition</span></div>
    <div style="display:flex;align-items:center;gap:6px;width:120px"><input type="range" min="1" max="6" step="0.25" value="${S.zoom}" id="tlzoom" aria-label="Zoom"></div></div>`;
  if (!tl.length) {
    $("#tl").innerHTML = `${head}<div class="tlempty">The Cutter lays the edit out here: every shot, transition, line of text and beat of the music.</div>`;
    paintRanges();
    return;
  }
  const avail = Math.max(200, $("#tl").clientWidth - 52 - 24);
  const pxs = (avail / dur) * S.zoom;
  S.pxs = pxs;
  const W = Math.ceil(dur * pxs) + 20;
  const step = [0.5, 1, 2, 5, 10, 15, 30, 60].find((s) => s * pxs >= 56) || 60;
  let ruler = "";
  for (let t = 0; t <= dur + 1e-6; t += step / 2) {
    const maj = Math.abs(t / step - Math.round(t / step)) < 1e-6;
    ruler += `<i class="${maj ? "maj" : ""}" style="left:${t * pxs}px"></i>${maj ? `<span style="left:${t * pxs}px">${t >= 60 ? fmt(t).slice(0, 5) : `${+t.toFixed(1)}s`}</span>` : ""}`;
  }
  const blocks = tl.map((g, i) => {
    const L = segLen(g), left = g.start * pxs, w = Math.max(2, L * pxs - 1);
    const bg = g.thumb ? `background-image:url('${pf(g.thumb, S.outBust)}')` : g.kind === "clip" ? `background-image:url('${pf(p.clips.find((c) => c.id === g.clip)?.poster, 1)}')` : "";
    return `<div class="blk ${g.kind === "card" ? "card" : ""}" data-i="${i}" style="left:${left}px;width:${w}px;--c:${ROLE[g.role] || "#7aa2f7"};${bg}"><span>${w > 46 ? `${g.role} ${L.toFixed(1)}s` : ""}</span></div>
      ${g.trans !== "cut" ? `<div class="tr" title="${esc(g.trans)}" style="left:${(g.start + g.trans_d / 2) * pxs}px"></div>` : ""}`;
  }).join("");
  const texts = (p.texts || []).map((t) => `<div class="txt ${t.kind}" style="left:${t.start * pxs}px;width:${Math.max(4, (t.end - t.start) * pxs - 1)}px" title="${esc(t.text)}">${esc(t.text)}</div>`).join("");
  $("#tl").innerHTML = `${head}<div class="tlbody"><div class="tlabels"><div></div><div>V1</div><div>TXT</div><div>A1</div></div>
    <div class="tlscroll" id="tlscroll"><div class="tlin" style="width:${W}px">
      <div class="ruler" id="ruler">${ruler}</div><div class="vtrack">${blocks}</div><div class="ttrack">${texts}</div>
      <div class="atrack" id="atrack"><canvas id="wave"></canvas></div><div class="playhead" id="ph" style="left:0"></div></div></div></div>`;
  paintRanges();
  drawWave(dur, pxs);
  const vid = $("#vid");
  movePlayhead(vid ? vid.currentTime : 0);
}

function drawWave(dur, pxs) {
  const p = S.p, tr = p.track, cv = $("#wave"), box = $("#atrack");
  if (!cv || !box) return;
  const w = Math.ceil(dur * pxs) + 20, h = box.clientHeight || 60, dpr = window.devicePixelRatio || 1;
  cv.width = w * dpr; cv.height = h * dpr; cv.style.width = `${w}px`; cv.style.height = `${h}px`;
  const ctx = cv.getContext("2d");
  ctx.scale(dpr, dpr);
  const mid = h / 2;
  if (!tr || !tr.peaks?.length) {
    ctx.fillStyle = "#5b616b"; ctx.font = "11px Segoe UI, sans-serif";
    ctx.fillText(p.clips.some((c) => c.has_audio) ? "footage sound only" : "no music · silent footage", 8, mid + 4);
    return;
  }
  const mi = p.audio?.music_in || 0, n = tr.peaks.length;
  ctx.fillStyle = "rgba(115, 218, 202, 0.55)";
  for (let x = 0; x < dur * pxs; x += 2) {
    const t = mi + x / pxs;
    const v = tr.peaks[Math.min(n - 1, Math.floor((t / tr.duration) * n))] || 0;
    const fade = Math.min(1, (dur - x / pxs) / Math.max(0.1, p.audio?.fade_out || 2));
    const bh = Math.max(1, v * (h - 14) * fade);
    ctx.fillRect(x, mid - bh / 2, 1.4, bh);
  }
  const down = new Set((tr.downbeats || []).map((b) => b.toFixed(3)));
  for (const b of tr.beats) {
    const t = b - mi;
    if (t < 0 || t > dur) continue;
    const isDown = down.has(b.toFixed(3));
    ctx.fillStyle = isDown ? "rgba(255,255,255,.55)" : "rgba(255,255,255,.18)";
    ctx.fillRect(t * pxs, 0, 1, isDown ? 8 : 5);
  }
  ctx.fillStyle = "#ff5b35";
  for (const g of p.timeline.slice(1)) {
    const t = g.start + (g.trans !== "cut" ? g.trans_d / 2 : 0);
    ctx.fillRect(t * pxs - 0.5, h - 8, 1.5, 8);
  }
}

function movePlayhead(t) {
  const ph = $("#ph");
  if (ph && S.pxs) ph.style.left = `${t * S.pxs}px`;
}

// ---------------------------------------------------------------- actions
function setS(key, val, rerender = true) {
  S.p.settings[key] = val;
  clearTimeout(S.saveT);
  S.saveT = setTimeout(saveSettings, 300);
  if (rerender) renderInsp();
  if (key === "aspect") renderViewer(true);
  if (key === "skill" || key === "music") renderBin();
}
async function saveSettings() {
  clearTimeout(S.saveT);
  S.saveT = null;
  try { await api(`/api/projects/${S.pid}`, { method: "PATCH", body: JSON.stringify({ settings: S.p.settings }) }); }
  catch (e) { toast(`Couldn't save: ${e.message}`, true); }
}

async function run() {
  if (S.running || !S.p.clips.length) return;
  if (S.saveT) await saveSettings();
  S.running = true; S.view = "auto"; S.live = null; S.tick = null;
  renderTop();
  try { await api(`/api/projects/${S.pid}/run`, { method: "POST" }); }
  catch (e) { S.running = false; toast(e.message, true); renderTop(); }
}

function upload(files, kind) {
  let chain = Promise.resolve();
  for (const file of files) {
    chain = chain.then(() => new Promise((resolve) => {
      const u = { name: file.name, pct: 0, kind };
      S.uploads.push(u);
      renderBin();
      if (!S.p.clips.length) renderViewer(true);
      const fd = new FormData();
      fd.append("kind", kind);
      fd.append("file", file);
      const x = new XMLHttpRequest();
      x.open("POST", `/api/projects/${S.pid}/upload`);
      x.upload.onprogress = (e) => { if (e.lengthComputable) { u.pct = Math.round((e.loaded / e.total) * 100); renderBin(); } };
      x.onload = () => {
        S.uploads = S.uploads.filter((y) => y !== u);
        if (x.status < 300) { S.p = JSON.parse(x.responseText); renderAll(); toast(kind === "clip" ? `${file.name}: the Intake agent is measuring it` : kind === "reference" ? "The Reference agent is watching your reference" : "Music added"); }
        else { let m = x.statusText; try { m = JSON.parse(x.responseText).detail; } catch { /* keep */ } toast(m, true); renderBin(); }
        resolve();
      };
      x.onerror = () => { S.uploads = S.uploads.filter((y) => y !== u); toast("Upload failed", true); renderBin(); resolve(); };
      x.send(fd);
    }));
  }
}

async function showProjects() {
  const menu = $("#menu");
  if (menu.classList.contains("open")) { menu.classList.remove("open"); return; }
  const list = await api("/api/projects");
  menu.innerHTML = list.map((p) => `<a href="?p=${p.id}">${p.poster.endsWith("/") ? '<span class="ph"></span>' : `<img src="${p.poster}" alt="">`}<span><b>${esc(p.name)}</b><small>${new Date(p.created * 1000).toLocaleString()} · ${p.clips} clip${p.clips === 1 ? "" : "s"}${p.duration ? ` · ${p.duration.toFixed(1)}s` : ""}</small></span></a>`).join("") || '<p class="lead" style="padding:8px">No edits yet.</p>';
  menu.classList.add("open");
}

function bindGlobal() {
  document.addEventListener("click", async (e) => {
    if (!e.target.closest(".proj")) $("#menu")?.classList.remove("open");
    const t = e.target.closest("[data-act]");
    if (!t) return;
    const act = t.dataset.act;
    if (act === "run") run();
    else if (act === "new") { const p = await api("/api/projects", { method: "POST", body: "{}" }); location.href = `?p=${p.id}`; }
    else if (act === "projects") showProjects();
    else if (act === "pick") $(`#f-${t.dataset.kind}`).click();
    else if (act === "del-clip") { S.p = await api(`/api/projects/${S.pid}/clips/${t.dataset.id}`, { method: "DELETE" }); renderAll(); }
    else if (act === "del-ref") { S.p = await api(`/api/projects/${S.pid}/reference`, { method: "DELETE" }); renderAll(); }
    else if (act === "tab") { S.tab = t.dataset.tab; S.station = null; renderInsp(); renderLine(); }
    else if (act === "set") setS(t.dataset.key, JSON.parse(t.dataset.v));
    else if (act === "toggle") setS(t.dataset.key, !S.p.settings[t.dataset.key]);
