    else if (act === "listen") {
      const aud = $("#aud"), f = t.dataset.file;
      if (S.playingFile === f) { aud.pause(); S.playingFile = null; }
      else { aud.src = `/music/${encodeURIComponent(f)}`; aud.play(); S.playingFile = f; }
      renderBin();
    } else if (act === "station") { S.station = S.station === t.dataset.key ? null : t.dataset.key; renderInsp(); renderLine(); }
    else if (act === "back") { S.station = null; renderInsp(); renderLine(); }
