  });
  document.addEventListener("change", async (e) => {
    const t = e.target;
    if (t.id === "pname") { S.p.name = t.value; await api(`/api/projects/${S.pid}`, { method: "PATCH", body: JSON.stringify({ name: t.value }) }); }
    if (t.type === "file" && t.files.length) {
      const kind = t.id.slice(2);
      upload([...t.files], kind);
      t.value = "";
    }
  });
  document.addEventListener("pointerdown", (e) => {
    const cmp = e.target.closest("#cmp");
    if (cmp) {
      const move = (ev) => { const r = cmp.getBoundingClientRect(); S.cmpX = clamp(((ev.clientX - r.left) / r.width) * 100, 0, 100); cmp.style.setProperty("--x", `${S.cmpX}%`); };
      move(e);
      const up = () => { window.removeEventListener("pointermove", move); window.removeEventListener("pointerup", up); };
      window.addEventListener("pointermove", move);
      window.addEventListener("pointerup", up);
    }
    const sc = e.target.closest("#tlscroll");
    if (sc && S.pxs && !e.target.closest(".blk,.txt")) {
      const r = sc.getBoundingClientRect();
      seek(Math.max(0, (e.clientX - r.left + sc.scrollLeft) / S.pxs));
    }
  });
  document.addEventListener("click", (e) => {
    const b = e.target.closest(".blk");
    if (b && S.p.timeline[+b.dataset.i]) seek(S.p.timeline[+b.dataset.i].start + 0.01);
  });
  const tip = $("#tip");
  document.addEventListener("mousemove", (e) => {
    const b = e.target.closest(".blk");
    if (!b) { tip.style.display = "none"; return; }
    const g = S.p.timeline[+b.dataset.i];
    if (!g) return;
    const L = segLen(g);
    tip.innerHTML = g.kind === "card" ? `<b>card · ${L.toFixed(2)}s</b>black, for the ${g.why || "title"}`
      : `<b>${esc(g.role)} · ${L.toFixed(2)}s at ${g.start.toFixed(2)}s</b>${esc(g.clip)} ${g.src_in.toFixed(2)}–${g.src_out.toFixed(2)}s${g.speed !== 1 ? ` · ${Math.round(g.speed * 100)}% speed` : ""}${g.zoom0 !== 1 || g.zoom1 !== 1 ? ` · zoom ${g.zoom0}→${g.zoom1}` : ""}${g.trans !== "cut" ? ` · ${g.trans} in` : ""}<br><span style="color:var(--mut)">${esc(g.why)}</span>`;
    tip.style.display = "block";
    tip.style.left = `${Math.min(e.clientX + 14, innerWidth - 320)}px`;
    tip.style.top = `${e.clientY - 70}px`;
  });
  document.addEventListener("keydown", (e) => {
    if (e.code === "Space" && !/INPUT|TEXTAREA/.test(document.activeElement?.tagName)) { e.preventDefault(); const v = $("#vid"); if (v) v.paused ? v.play() : v.pause(); }
    if ((e.ctrlKey || e.metaKey) && e.key === "Enter") run();
  });
  // drag & drop anywhere
  const dz = $("#dz");
  let depth = 0;
  window.addEventListener("dragenter", (e) => { if (e.dataTransfer?.types?.includes("Files")) { depth++; dz.classList.add("on"); } });
  window.addEventListener("dragleave", () => { depth = Math.max(0, depth - 1); if (!depth) dz.classList.remove("on"); });
  window.addEventListener("dragover", (e) => { e.preventDefault(); document.querySelectorAll("#dz > div").forEach((d) => d.classList.toggle("hover", d.contains(e.target))); });
  window.addEventListener("drop", (e) => {
    e.preventDefault();
    depth = 0;
    dz.classList.remove("on");
    const files = [...(e.dataTransfer?.files || [])];
    if (!files.length) return;
    const zone = e.target.closest?.("#dz > div")?.dataset.kind;
    const audio = files.filter((f) => f.type.startsWith("audio/"));
    const video = files.filter((f) => !f.type.startsWith("audio/"));
    if (zone === "reference" && video.length) upload([video[0]], "reference");
    else if (zone === "music" || (audio.length && !video.length)) upload([(audio[0] || files[0])], "music");
    else upload(video, "clip");
  });
  window.addEventListener("resize", () => { fitFrame(); renderTL(); });
}

