def apply_trim(x: np.ndarray, trim: dict | None) -> np.ndarray:
    """The colourist's final trim after the look: exposure (stops) and a contrast ease (1 = none)."""
    if not trim:
        return x
    e, c = float(trim.get("exposure", 0)), float(trim.get("contrast", 1))
    if e:
        x = to_srgb(to_linear(x) * 2 ** e)
    if abs(c - 1) > 1e-3:
        x = np.clip(x, 0, 1)
        x = np.where(x < 0.45, 0.45 * (x / 0.45) ** c, 1 - 0.55 * ((1 - x) / 0.55) ** c)
    return np.clip(x, 0, 1)


def grade_fn(primary: dict, look: dict, look_strength: float, match: dict | None = None,
             trim: dict | None = None) -> Callable[[np.ndarray], np.ndarray]:
    def f(x: np.ndarray) -> np.ndarray:
        x = apply_primary(x, primary)
        if match:
            x = transfer(x, match["src"], match["ref"], match["strength"])
        return apply_trim(apply_look(x, look, look_strength), trim)
