def lut_for(ctx: Ctx, clip: Clip, lk: dict, strength: float, match: dict | None, tag: str,
            trim: dict | None = None) -> tuple[str, dict]:
    px = clip_pixels(ctx, clip)
    prim = look.primary_params(px)
    key = hashlib.sha1(json.dumps([prim, lk, strength, match, trim], sort_keys=True, default=str).encode()).hexdigest()[:10]
    rel = f"looks/{clip.id}_{tag}_{key}.cube"
    if not ctx.abs(rel).exists():
        look.write_cube(ctx.abs(rel), look.bake(look.grade_fn(prim, lk, strength, match, trim)), title=f"cutroom {tag} {clip.id}")
    return rel, prim


def self_correct(px: np.ndarray, prim: dict, lk: dict, strength: float, match: dict | None) -> tuple[dict | None, list[str]]:
    """Grade, measure, and trim until the clip neither crushes nor blows out and sits at a usable exposure
    (the colourist's last pass after a look: a look is a direction, not a licence to lose the picture)."""
    trim: dict = {"exposure": 0.0, "contrast": 1.0}
    notes = []
    for _ in range(6):
        st = look.stats(look.grade_fn(prim, lk, strength, match, trim)(px))
        mid, lo, hi = st["luma"][2], st["clip_lo"], st["clip_hi"]
        if lo <= 0.035 and hi <= 0.025 and 0.22 <= mid <= 0.64:
            break
        if lo > 0.035 or mid < 0.22:
            trim["exposure"] = round(trim["exposure"] + (0.35 if mid < 0.2 else 0.2), 2)
            trim["contrast"] = round(max(0.8, trim["contrast"] - 0.05), 2)
        elif hi > 0.025 or mid > 0.64:
            trim["exposure"] = round(trim["exposure"] - 0.2, 2)
        notes.append(f"mid-grey {mid:.2f}, {lo:.0%} crushed, {hi:.0%} blown")
    if trim == {"exposure": 0.0, "contrast": 1.0}:
        return None, []
    return trim, notes

